export function createHttpCache(db) {
  const selectStmt = db.prepare('SELECT payload, fetched_at FROM http_cache WHERE cache_key = ?');
  const upsertStmt = db.prepare(`
    INSERT INTO http_cache (cache_key, payload, fetched_at) VALUES (?, ?, ?)
    ON CONFLICT (cache_key) DO UPDATE SET payload = excluded.payload, fetched_at = excluded.fetched_at
  `);

  return {
    get(key, maxAgeMs) {
      const row = selectStmt.get(key);
      if (!row || Date.now() - row.fetched_at > maxAgeMs) return undefined;
      return JSON.parse(row.payload);
    },

    set(key, value) {
      upsertStmt.run(key, JSON.stringify(value), Date.now());
    },
  };
}

export const USER_AGENT = 'haiku-pwa/0.1 (personal comic collection; +https://github.com/angelospillos/haiku-pwa)';

export const CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000;

export async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const index = next++;
      results[index] = await fn(items[index], index);
    }
  });
  await Promise.all(workers);
  return results;
}

export function cleanText(value, max) {
  if (typeof value !== 'string') return '';
  return value.replace(/\s+/g, ' ').trim().slice(0, max);
}

import { CACHE_TTL_MS, USER_AGENT, cleanText, mapLimit } from './util.js';

const MAX_CANDIDATES = 8;
const DETAIL_CONCURRENCY = 3;
const TIMEOUT_MS = 10_000;

export class SourceError extends Error {}

export function createComicsOrgClient({ baseUrl, cache, fetchImpl = fetch }) {
  async function getJson(url) {
    const cached = cache.get(`comicsorg:${url}`, CACHE_TTL_MS);
    if (cached) return cached;

    let response;
    try {
      response = await fetchImpl(url, {
        headers: { Accept: 'application/json', 'User-Agent': USER_AGENT },
        signal: AbortSignal.timeout(TIMEOUT_MS),
      });
    } catch (error) {
      throw new SourceError(`comics.org could not be reached (${error.name})`);
    }
    if (response.status === 404) return null;
    if (!response.ok) throw new SourceError(`comics.org responded with HTTP ${response.status}`);

    const json = await response.json();
    cache.set(`comicsorg:${url}`, json);
    return json;
  }

  function issueIdFrom(apiUrl) {
    const match = /\/issue\/(\d+)\//.exec(apiUrl ?? '');
    return match ? match[1] : null;
  }

  function toCandidate(summary, detail) {
    const sourceId = issueIdFrom(summary.api_url);
    return {
      source: 'comics.org',
      sourceId,
      sourceUrl: sourceId ? `https://www.comics.org/issue/${sourceId}/` : null,
      seriesTitle: cleanText(summary.series_name, 200),
      title: cleanText(detail?.title || summary.descriptor, 200),
      publicationDate: cleanText(detail?.publication_date || summary.publication_date, 40),
      coverUrl: typeof detail?.cover === 'string' && detail.cover.startsWith('https://') ? detail.cover : null,
    };
  }

  return {
    async searchIssues({ series, number, year }) {
      const base = `${baseUrl}/series/name/${encodeURIComponent(series)}/issue/${encodeURIComponent(number)}/`;
      const url = `${base}${year ? `year/${encodeURIComponent(year)}/` : ''}?format=json`;
      const list = await getJson(url);
      const summaries = (list?.results ?? []).filter((item) => !item.variant_of).slice(0, MAX_CANDIDATES);

      const details = await mapLimit(summaries, DETAIL_CONCURRENCY, async (summary) => {
        if (!summary.api_url) return null;
        try {
          return await getJson(summary.api_url);
        } catch {
          return null;
        }
      });

      return summaries
        .map((summary, index) => toCandidate(summary, details[index]))
        .filter((candidate) => candidate.sourceId);
    },
  };
}

import fs from 'node:fs';
import path from 'node:path';
import readline from 'node:readline';
import { DatabaseSync } from 'node:sqlite';

export const INDUCKS_MEMBERS = [
  'inducks_issue.isv',
  'inducks_publication.isv',
  'inducks_publicationname.isv',
  'inducks_countryname.isv',
];

const SCHEMA = `
CREATE TABLE country (countrycode TEXT PRIMARY KEY, countryname TEXT NOT NULL);
CREATE TABLE publication (publicationcode TEXT PRIMARY KEY, countrycode TEXT, title TEXT NOT NULL);
CREATE TABLE publication_name (publicationcode TEXT NOT NULL, publicationname TEXT NOT NULL);
CREATE TABLE issue (
  issuecode TEXT PRIMARY KEY,
  publicationcode TEXT NOT NULL,
  issuenumber TEXT NOT NULL,
  title TEXT,
  oldestdate TEXT
);
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
`;

const INDEXES = `
CREATE INDEX issue_number ON issue (issuenumber);
CREATE INDEX publication_name_code ON publication_name (publicationcode);
`;

async function* readIsv(file) {
  if (!fs.existsSync(file)) throw new Error(`Missing Inducks file: ${file}`);
  const lines = readline.createInterface({
    input: fs.createReadStream(file, { encoding: 'utf8' }),
    crlfDelay: Infinity,
  });
  let isHeader = true;
  for await (const line of lines) {
    if (isHeader) {
      isHeader = false;
      continue;
    }
    if (line) yield line.split('^');
  }
}

export async function importInducks({ dir, dbPath }) {
  const tmpPath = `${dbPath}.tmp`;
  fs.mkdirSync(path.dirname(dbPath), { recursive: true });
  fs.rmSync(tmpPath, { force: true });

  const db = new DatabaseSync(tmpPath);
  const counts = { countries: 0, publications: 0, publicationNames: 0, issues: 0 };
  try {
    db.exec(SCHEMA);
    db.exec('BEGIN');

    const insertCountry = db.prepare('INSERT OR IGNORE INTO country VALUES (?, ?)');
    for await (const [countrycode, languagecode, countryname] of readIsv(path.join(dir, 'inducks_countryname.isv'))) {
      if (languagecode === 'en' && countrycode && countryname) {
        insertCountry.run(countrycode, countryname);
        counts.countries++;
      }
    }

    const insertPublication = db.prepare('INSERT OR IGNORE INTO publication VALUES (?, ?, ?)');
    for await (const [publicationcode, countrycode, , title] of readIsv(path.join(dir, 'inducks_publication.isv'))) {
      if (publicationcode && title) {
        insertPublication.run(publicationcode, countrycode, title);
        counts.publications++;
      }
    }

    const insertPublicationName = db.prepare('INSERT INTO publication_name VALUES (?, ?)');
    for await (const [publicationcode, publicationname] of readIsv(path.join(dir, 'inducks_publicationname.isv'))) {
      if (publicationcode && publicationname) {
        insertPublicationName.run(publicationcode, publicationname);
        counts.publicationNames++;
      }
    }

    const insertIssue = db.prepare('INSERT OR IGNORE INTO issue VALUES (?, ?, ?, ?, ?)');
    for await (const fields of readIsv(path.join(dir, 'inducks_issue.isv'))) {
      if (fields.length < 11) continue;
      const [issuecode, , publicationcode, issuenumber, title, , , , , , oldestdate] = fields;
      if (!issuecode || !publicationcode || !issuenumber) continue;
      insertIssue.run(issuecode, publicationcode, issuenumber, title || null, oldestdate && !oldestdate.startsWith('9999') ? oldestdate : null);
      counts.issues++;
    }

    db.exec('COMMIT');
    db.exec(INDEXES);
    const insertMeta = db.prepare('INSERT INTO meta VALUES (?, ?)');
    insertMeta.run('synced_at', new Date().toISOString());
    insertMeta.run('issues', String(counts.issues));
    insertMeta.run('publications', String(counts.publications));
    db.close();
    fs.renameSync(tmpPath, dbPath);
    return counts;
  } catch (error) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction open
    }
    db.close();
    fs.rmSync(tmpPath, { force: true });
    throw error;
  }
}

