import fs from 'node:fs';
import { DatabaseSync } from 'node:sqlite';
import { cleanText } from './util.js';

const MAX_CANDIDATES = 20;

function escapeLike(value) {
  return value.replace(/[\\%_]/g, (char) => `\\${char}`);
}

function validDate(value) {
  return value && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : '';
}

export function openInducksDb(file) {
  if (!fs.existsSync(file)) return null;
  return new DatabaseSync(file, { readOnly: true });
}

export function createInducksSource(db) {
  const syncedAt = db ? db.prepare("SELECT value FROM meta WHERE key = 'synced_at'").get()?.value : null;

  const searchStmt = db
    ? db.prepare(`
        SELECT i.issuecode, i.title AS issue_title, i.oldestdate,
               p.title AS publication_title, c.countryname
        FROM issue i
        JOIN publication p ON p.publicationcode = i.publicationcode
        LEFT JOIN country c ON c.countrycode = p.countrycode
        WHERE i.issuenumber = ?
          AND (
            p.title LIKE ? ESCAPE '\\'
            OR p.publicationcode IN (
              SELECT publicationcode FROM publication_name WHERE publicationname LIKE ? ESCAPE '\\'
            )
          )
        ORDER BY (p.title LIKE ? ESCAPE '\\') DESC, p.title, i.oldestdate
        LIMIT ?
      `)
    : null;

  return {
    get available() {
      return Boolean(db);
    },

    syncedAt,

    searchIssues({ series, number }) {
      if (!searchStmt) throw new Error('Inducks data has not been synced yet (run npm run sync:inducks)');
      const term = escapeLike(series);
      const rows = searchStmt.all(number, `%${term}%`, `%${term}%`, `${term}%`, MAX_CANDIDATES);
      return rows.map((row) => ({
        source: 'inducks',
        sourceId: row.issuecode,
        sourceUrl: `https://inducks.org/issue.php?${new URLSearchParams({ c: row.issuecode })}`,
        seriesTitle: cleanText([row.publication_title, row.countryname].filter(Boolean).join(' · '), 200),
        title: cleanText(row.issue_title ?? '', 200),
        publicationDate: validDate(row.oldestdate),
        coverUrl: null,
      }));
    },
  };
}

async function attempt(task) {
  try {
    return { ok: true, candidates: await task() };
  } catch (error) {
    return { ok: false, candidates: [], message: error.message };
  }
}

function describe(outcome) {
  return outcome.ok
    ? { ok: true, count: outcome.candidates.length }
    : { ok: false, count: 0, message: outcome.message };
}

export async function lookupIssue({ series, number, year, comicsOrg, inducks }) {
  const [comicsOrgOutcome, inducksOutcome] = await Promise.all([
    attempt(() => comicsOrg.searchIssues({ series, number, year })),
    attempt(() =>
      inducks
        .searchIssues({ series, number })
        .filter((candidate) => !year || !candidate.publicationDate || candidate.publicationDate.startsWith(year)),
    ),
  ]);

  return {
    series,
    number,
    year: year || null,
    candidates: [...comicsOrgOutcome.candidates, ...inducksOutcome.candidates],
    sources: {
      'comics.org': describe(comicsOrgOutcome),
      inducks: describe(inducksOutcome),
    },
  };
}

import fs from 'node:fs';
import path from 'node:path';
import express from 'express';
import { createHttpCache } from './cache.js';
import { createCollection, DuplicateComicError } from './collection.js';
import { lookupIssue } from './lookup.js';
import { createComicsOrgClient } from './metadata/comicsorg.js';
import { createInducksSource } from './metadata/inducks.js';
import { cleanText } from './metadata/util.js';

const MAX_PHOTO_BYTES = 10 * 1024 * 1024;
const PHOTO_EXTENSIONS = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };
const MATCH_SOURCES = new Set(['comics.org', 'inducks']);

function parseIssueQuery(query, { allowYear = false } = {}) {
  const series = cleanText(query.series, 100);
  const number = cleanText(query.number, 20);
  const year = allowYear ? cleanText(query.year, 4) : '';
  if (!series) return { error: 'Series is required' };
  if (!number) return { error: 'Issue number is required' };
  if (year && !/^\d{4}$/.test(year)) return { error: 'Year must have four digits' };
  return { series, number, year };
}

function parsePhoto(value) {
  const match = typeof value === 'string' ? /^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=\s]+)$/.exec(value) : null;
  if (!match) return null;
  const bytes = Buffer.from(match[2], 'base64');
  if (bytes.length === 0 || bytes.length > MAX_PHOTO_BYTES) return null;
  return { bytes, extension: PHOTO_EXTENSIONS[match[1]] };
}

function httpsOnly(value, max) {
  const text = cleanText(value, max);
  return /^https:\/\//.test(text) ? text : null;
}

function sanitizeMatch(input) {
  if (!input || typeof input !== 'object' || !MATCH_SOURCES.has(input.source)) return null;
  return {
    source: input.source,
    sourceId: cleanText(input.sourceId, 80) || null,
    sourceUrl: httpsOnly(input.sourceUrl, 300),
    seriesTitle: cleanText(input.seriesTitle, 200) || null,
    title: cleanText(input.title, 200) || null,
    publicationDate: cleanText(input.publicationDate, 40) || null,
    coverUrl: httpsOnly(input.coverUrl, 500),
  };
}

function badRequest(res, error) {
  return res.status(400).json({ error });
}

export function createApp({ config, db, inducksDb, fetchImpl }) {
  const collection = createCollection(db, config.photosDir);
  const cache = createHttpCache(db);
  const comicsOrg = createComicsOrgClient({ baseUrl: config.comicsOrgApiUrl, cache, fetchImpl });
  const inducks = createInducksSource(inducksDb);

  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '15mb' }));

  app.get('/api/collection', (req, res) => {
    res.json({ items: collection.list(), series: collection.seriesNames() });
  });

  app.get('/api/collection/check', (req, res) => {
    const query = parseIssueQuery(req.query);
    if (query.error) return badRequest(res, query.error);
    const item = collection.find(query.series, query.number);
    res.json({ owned: Boolean(item), item });
  });

  app.post('/api/collection', (req, res) => {
    const series = cleanText(req.body?.series, 100);
    const number = cleanText(req.body?.number, 20);
    if (!series) return badRequest(res, 'Series is required');
    if (!number) return badRequest(res, 'Issue number is required');

    const photo = parsePhoto(req.body?.photo);
    if (!photo) return badRequest(res, 'A photo of the comic is required (JPEG, PNG or WebP, up to 10 MB)');

    try {
      const item = collection.add({ series, number, photo, match: sanitizeMatch(req.body?.match) });
      res.status(201).json({ item });
    } catch (error) {
      if (error instanceof DuplicateComicError) {
        return res.status(409).json({ error: error.message, item: error.existing });
      }
      throw error;
    }
  });

  app.delete('/api/comics/:id', (req, res) => {
    const id = Number(req.params.id);
    if (!Number.isInteger(id)) return badRequest(res, 'Invalid id');
    if (!collection.remove(id)) return res.status(404).json({ error: 'Not found' });
    res.status(204).end();
  });

  app.get('/api/comics/:id/photo', (req, res) => {
    const id = Number(req.params.id);
    const file = Number.isInteger(id) ? collection.photoPath(id) : null;
    if (!file || !fs.existsSync(file)) return res.status(404).end();
    res.sendFile(file, { headers: { 'Cache-Control': 'private, max-age=86400' } });
  });

  app.get('/api/lookup', async (req, res) => {
    const query = parseIssueQuery(req.query, { allowYear: true });
    if (query.error) return badRequest(res, query.error);
    res.json(await lookupIssue({ ...query, comicsOrg, inducks }));
  });

  app.use('/api', (req, res) => {
    res.status(404).json({ error: 'Not found' });
  });

  if (fs.existsSync(config.distDir)) {
    app.use(express.static(config.distDir));
  }
  app.use((req, res, next) => {
    if (req.method !== 'GET' && req.method !== 'HEAD') return next();
    const indexFile = path.join(config.distDir, 'index.html');
    if (!fs.existsSync(indexFile)) {
      return res.status(503).type('text').send('Client not built yet. Run `npm run build` or use `npm run dev`.');
    }
    return res.sendFile(indexFile);
  });

  app.use((error, req, res, next) => {
    if (error.type === 'entity.too.large') return res.status(413).json({ error: 'Photo is too large' });
    if (error.type === 'entity.parse.failed') return res.status(400).json({ error: 'Invalid JSON' });
    console.error(error);
    return res.status(500).json({ error: 'Something went wrong on the server' });
  });

  return app;
}

import { createApp } from './app.js';
import { loadConfig } from './config.js';
import { openCollectionDb } from './db.js';
import { openInducksDb } from './metadata/inducks.js';

const config = loadConfig();
const db = openCollectionDb(config.collectionDbPath);
const inducksDb = openInducksDb(config.inducksDbPath);
const app = createApp({ config, db, inducksDb });

app.listen(config.port, () => {
  console.log(`Comic collection listening on http://localhost:${config.port}`);
  console.log(`Collection database: ${config.collectionDbPath}`);
  console.log(
    inducksDb
      ? `Inducks database: ${config.inducksDbPath}`
      : `Inducks database not found at ${config.inducksDbPath} (run npm run sync:inducks)`,
  );
});

#!/usr/bin/env node
// Downloads the daily Inducks dump (https://inducks.org/inducks/isv.tgz) and
// imports the tables the app searches into data/inducks.sqlite.
//
// Options:
//   --archive <file.tgz>  use an already downloaded archive instead of downloading
//   --dir <isv-dir>       use already extracted .isv files instead

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { loadConfig } from '../config.js';
import { importInducks, INDUCKS_MEMBERS } from '../metadata/inducks-import.js';
import { USER_AGENT } from '../metadata/util.js';

const ARCHIVE_URL = 'https://inducks.org/inducks/isv.tgz';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--archive') args.archive = argv[++i];
    else if (argv[i] === '--dir') args.dir = argv[++i];
    else throw new Error(`Unknown option: ${argv[i]}`);
  }
  return args;
}

async function download(url, file) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  console.log(`Downloading ${url}`);
  const response = await fetch(url, { headers: { 'User-Agent': USER_AGENT } });
  if (!response.ok) throw new Error(`Download failed with HTTP ${response.status}`);
  await pipeline(Readable.fromWeb(response.body), fs.createWriteStream(file));
  console.log(`Saved ${(fs.statSync(file).size / 1048576).toFixed(1)} MB to ${file}`);
}

function extract(archive, destDir) {
  fs.mkdirSync(destDir, { recursive: true });
  const members = INDUCKS_MEMBERS.map((name) => `isv/${name}`);
  const result = spawnSync('tar', ['-xzf', archive, '-C', destDir, ...members], { stdio: 'inherit' });
  if (result.status !== 0) throw new Error(`Could not extract ${archive}`);
}

async function main() {
  const config = loadConfig();
  const args = parseArgs(process.argv.slice(2));
  const workDir = path.join(config.dataDir, 'inducks-download');

  let isvDir = args.dir;
  if (!isvDir) {
    const archive = args.archive ?? path.join(workDir, 'isv.tgz');
    if (!args.archive) await download(ARCHIVE_URL, archive);
    console.log('Extracting the tables the app needs');
    extract(archive, workDir);
    isvDir = path.join(workDir, 'isv');
  }

  console.log(`Importing Inducks data from ${isvDir}`);
  const counts = await importInducks({ dir: isvDir, dbPath: config.inducksDbPath });
