import { defineConfig } from 'vite';
import preact from '@preact/preset-vite';
import { VitePWA } from 'vite-plugin-pwa';

export default defineConfig({
  root: 'client',
  publicDir: 'public',
  plugins: [
    preact(),
    VitePWA({
      registerType: 'autoUpdate',
      includeAssets: ['icons/icon.svg', 'icons/apple-touch-icon.png'],
      manifest: {
        name: 'Comic Collection',
        short_name: 'Comics',
        description: 'Check an issue number, add it to your collection with a photo, and look up its details.',
        theme_color: '#1d4ed8',
        background_color: '#f5f1e8',
        display: 'standalone',
        start_url: '/',
        scope: '/',
        icons: [
          { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' },
          { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png' },
          { src: '/icons/icon-512-maskable.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
        ],
      },
      workbox: {
        navigateFallback: '/index.html',
        navigateFallbackDenylist: [/^\/api\//],
      },
    }),
  ],
  build: {
    outDir: '../dist',
    emptyOutDir: true,
  },
  server: {
    port: 5173,
    proxy: {
      '/api': `http://localhost:${process.env.PORT || 3000}`,
    },
  },
});

import { render } from 'preact';
import { App } from './App.jsx';
import './styles.css';

render(<App />, document.getElementById('app'));

const CONNECTION_ERROR = "Can't reach the collection server. Check the connection and try again.";

function query(params) {
  return new URLSearchParams(Object.entries(params).filter(([, value]) => value)).toString();
}

async function request(path, options = {}) {
  let response;
  try {
    response = await fetch(path, {
      ...options,
      headers: { Accept: 'application/json', ...(options.body ? { 'Content-Type': 'application/json' } : {}) },
    });
  } catch {
    throw new Error(CONNECTION_ERROR);
  }

  const body = await response.json().catch(() => ({}));
  if (!response.ok) {
    const error = new Error(body.error || `Request failed (HTTP ${response.status})`);
    error.status = response.status;
    error.item = body.item;
    throw error;
  }
  return body;
}

export const api = {
  list() {
    return request('/api/collection');
  },

  check(series, number) {
    return request(`/api/collection/check?${query({ series, number })}`);
  },

  lookup(series, number, year) {
    return request(`/api/lookup?${query({ series, number, year })}`);
  },

  add(entry) {
    return request('/api/collection', { method: 'POST', body: JSON.stringify(entry) });
  },

  remove(id) {
    return request(`/api/comics/${id}`, { method: 'DELETE' });
  },
};

const MAX_SIDE = 1280;
const JPEG_QUALITY = 0.85;

function loadImage(url) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error('Could not read image'));
    image.src = url;
  });
}

export async function fileToJpegDataUrl(file) {
  const url = URL.createObjectURL(file);
  try {
    const image = await loadImage(url);
    const scale = Math.min(1, MAX_SIDE / Math.max(image.naturalWidth, image.naturalHeight));
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(image.naturalWidth * scale);
    canvas.height = Math.round(image.naturalHeight * scale);
    canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', JPEG_QUALITY);
  } finally {
    URL.revokeObjectURL(url);
  }
}

export const SOURCE_NAMES = {
  'comics.org': 'comics.org',
  inducks: 'Inducks',
};

export function formatDate(iso) {
  if (!iso) return '';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}

import { SOURCE_NAMES, formatDate } from './format.js';

export function ComicDetails({ item }) {
  const hasCatalogue = Boolean(item.source);
  return (
    <ul class="details">
      {item.title && <li>{item.title}</li>}
      {item.seriesTitle && <li class="muted">{item.seriesTitle}</li>}
      {item.publicationDate && <li class="muted">Published {item.publicationDate}</li>}
      <li class="muted">Added {formatDate(item.createdAt)}</li>
      {hasCatalogue ? (
        <li>
          <a href={item.sourceUrl} target="_blank" rel="noreferrer">
            Details on {SOURCE_NAMES[item.source] ?? item.source} ↗
          </a>
        </li>
      ) : (
        <li class="muted">No catalogue details saved</li>
      )}
    </ul>
  );
}

import { ComicDetails } from './ComicDetails.jsx';

export function CollectionList({ items, onRemove }) {
  if (items.length === 0) {
    return (
      <section class="card">
        <h2>My collection</h2>
        <p class="empty">Nothing here yet. Check an issue to add your first one.</p>
      </section>
    );
  }

  return (
    <section>
      <h2>
        My collection <span class="muted">({items.length})</span>
      </h2>
      <ul class="collection">
        {items.map((item) => (
          <li key={item.id} class="collection-item">
            <img src={item.photoUrl} alt={`Photo of ${item.series} #${item.number}`} loading="lazy" />
            <div class="collection-text">
              <h3>
                {item.series} #{item.number}
              </h3>
              <ComicDetails item={item} />
            </div>
            <button
              type="button"
              class="ghost danger"
              aria-label={`Remove ${item.series} #${item.number}`}
              onClick={() => onRemove(item)}
            >
              Remove
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

import { useRef, useState } from 'preact/hooks';
import { api } from './api.js';
import { ComicDetails } from './ComicDetails.jsx';
import { fileToJpegDataUrl } from './photo.js';
import { SOURCE_NAMES } from './format.js';

const IDLE_LOOKUP = { loading: false, data: null, error: '' };

function MatchList({ lookup, choice, onChoice }) {
  if (lookup.loading) {
    return <p class="muted" role="status">Searching comics.org and Inducks…</p>;
  }
  if (lookup.error) {
    return <p class="alert" role="alert">Lookup failed: {lookup.error}</p>;
  }
  if (!lookup.data) return null;

  const { candidates, sources } = lookup.data;
  return (
    <>
      <ul class="sources">
        {Object.entries(sources).map(([name, status]) => (
          <li key={name}>
            <strong>{SOURCE_NAMES[name] ?? name}:</strong>{' '}
            {status.ok ? `${status.count} match${status.count === 1 ? '' : 'es'}` : `unavailable (${status.message})`}
          </li>
        ))}
      </ul>

      <fieldset class="candidates">
        <legend>Which issue is it?</legend>
        {candidates.map((candidate, index) => (
          <label class="candidate" key={`${candidate.source}-${candidate.sourceId}`}>
            <input
              type="radio"
              name="match"
              value={String(index)}
              checked={choice === String(index)}
              onChange={() => onChoice(String(index))}
            />
            {candidate.coverUrl ? (
              <img src={candidate.coverUrl} alt="" loading="lazy" />
            ) : (
              <span class="cover-placeholder" aria-hidden="true">
                {SOURCE_NAMES[candidate.source]}
              </span>
            )}
            <span class="candidate-text">
              <strong>{candidate.seriesTitle}</strong>
              {candidate.title && <span>{candidate.title}</span>}
              {candidate.publicationDate && <span class="muted">{candidate.publicationDate}</span>}
              <a href={candidate.sourceUrl} target="_blank" rel="noreferrer">
                View on {SOURCE_NAMES[candidate.source]} ↗
              </a>
            </span>
          </label>
        ))}
        <label class="candidate none">
          <input
            type="radio"
            name="match"
            value="none"
            checked={choice === 'none'}
            onChange={() => onChoice('none')}
          />
          <span>{candidates.length ? 'None of these: save without details' : 'Save without details'}</span>
        </label>
      </fieldset>
    </>
  );
}

function OwnedCard({ item, onAgain }) {
  return (
    <section class="card owned" aria-labelledby="owned-title">
      <p class="badge">✓ Already in your collection</p>
      <div class="owned-body">
        <img src={item.photoUrl} alt={`Your photo of ${item.series} #${item.number}`} />
        <div>
          <h2 id="owned-title">
            {item.series} #{item.number}
          </h2>
          <ComicDetails item={item} />
        </div>
      </div>
      <button type="button" class="secondary" onClick={onAgain}>
        Check another issue
      </button>
    </section>
  );
}

function MissingIssue({ checked, lookup, choice, onChoice, photo, onPhoto, onSave, onCancel, saving }) {
  return (
    <section class="card" aria-labelledby="missing-title">
      <h2 id="missing-title">
        {checked.series} #{checked.number} isn't in your collection yet
      </h2>

      <h3>1. Pick the matching issue (optional)</h3>
      <MatchList lookup={lookup} choice={choice} onChoice={onChoice} />

      <h3>2. Photograph the cover</h3>
      <label class="button secondary file-button">
        📷 {photo ? 'Retake photo' : 'Take photo'}
        <input
          type="file"
          accept="image/*"
          capture="environment"
          class="sr-only"
          aria-label="Take photo of the comic"
          onChange={onPhoto}
        />
      </label>
      {photo && <img class="preview" src={photo.dataUrl} alt="Photo of the comic to be saved" />}

      <div class="actions">
        <button type="button" class="primary" disabled={!photo || saving} onClick={onSave}>
          {saving ? 'Saving…' : 'Add to collection'}
        </button>
        <button type="button" class="ghost" onClick={onCancel}>
          Cancel
        </button>
      </div>
      {!photo && <p class="muted hint">A photo is needed before the issue can be saved.</p>}
    </section>
  );
}

export function CheckIssue({ series, onSeriesChange, seriesOptions, onSaved }) {
  const [number, setNumber] = useState('');
  const [year, setYear] = useState('');
  const [phase, setPhase] = useState('idle');
  const [owned, setOwned] = useState(null);
  const [checked, setChecked] = useState(null);
  const [lookup, setLookup] = useState(IDLE_LOOKUP);
  const [choice, setChoice] = useState('none');
  const [photo, setPhoto] = useState(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const requestRef = useRef(0);

  function reset() {
    requestRef.current++;
    setNumber('');
    setPhase('idle');
    setOwned(null);
    setChecked(null);
    setLookup(IDLE_LOOKUP);
    setChoice('none');
    setPhoto(null);
    setError('');
  }

  async function runLookup(requestId, seriesName, issueNumber, issueYear) {
    try {
      const data = await api.lookup(seriesName, issueNumber, issueYear);
      if (requestId === requestRef.current) setLookup({ loading: false, data, error: '' });
    } catch (err) {
      if (requestId === requestRef.current) setLookup({ loading: false, data: null, error: err.message });
    }
  }

  async function onCheck(event) {
    event.preventDefault();
    const seriesName = series.trim();
    const issueNumber = number.trim();
    if (!seriesName) return setError('Enter the series first, for example Asterix.');
    if (!issueNumber) return setError('Enter an issue number.');

    const requestId = ++requestRef.current;
    setError('');
    setPhase('checking');
    setOwned(null);
    setPhoto(null);
    setChoice('none');
    try {
      const result = await api.check(seriesName, issueNumber);
      if (requestId !== requestRef.current) return;
      if (result.owned) {
        setOwned(result.item);
        setPhase('owned');
        return;
      }
      const issueYear = year.trim();
      setChecked({ series: seriesName, number: issueNumber, year: issueYear });
      setLookup({ loading: true, data: null, error: '' });
      setPhase('missing');
      runLookup(requestId, seriesName, issueNumber, issueYear);
    } catch (err) {
      if (requestId !== requestRef.current) return;
      setError(err.message);
      setPhase('idle');
    }
  }

  async function onPhoto(event) {
    const file = event.currentTarget.files?.[0];
    event.currentTarget.value = '';
    if (!file) return;
    try {
      setPhoto({ dataUrl: await fileToJpegDataUrl(file) });
      setError('');
    } catch {
      setError("That picture couldn't be read. Try taking it again.");
    }
  }

  async function onSave() {
    const candidate = choice === 'none' ? null : lookup.data?.candidates[Number(choice)];
    setSaving(true);
    setError('');
    try {
      const { item } = await api.add({
        series: checked.series,
        number: checked.number,
        photo: photo.dataUrl,
        match: candidate ?? undefined,
      });
      onSaved(item);
      reset();
    } catch (err) {
      if (err.status === 409 && err.item) {
        setOwned(err.item);
        setPhase('owned');
      } else {
        setError(err.message);
      }
    } finally {
      setSaving(false);
    }
  }

  return (
    <div class="check">
      <form class="check-form card" onSubmit={onCheck}>
        <label class="field">
          <span>Series</span>
          <input
            type="text"
            list="series-options"
            value={series}
            placeholder="e.g. Asterix"
            autocomplete="off"
            onInput={(event) => onSeriesChange(event.currentTarget.value)}
          />
        </label>
        <datalist id="series-options">
          {seriesOptions.map((name) => (
            <option key={name} value={name} />
          ))}
        </datalist>

        <div class="row">
          <label class="field grow">
            <span>Issue number</span>
            <input
              type="text"
              inputmode="text"
              value={number}
              placeholder="e.g. 5"
              autocomplete="off"
              onInput={(event) => setNumber(event.currentTarget.value)}
            />
          </label>
          <label class="field year">
            <span>Year (optional)</span>
            <input
              type="text"
              inputmode="numeric"
              maxLength={4}
              value={year}
              placeholder="1965"
              autocomplete="off"
              onInput={(event) => setYear(event.currentTarget.value)}
            />
          </label>
        </div>

        <button type="submit" class="primary" disabled={phase === 'checking'}>
          {phase === 'checking' ? 'Checking…' : 'Check issue'}
        </button>
      </form>

      {error && (
        <p class="alert" role="alert">
          {error}
        </p>
      )}

      {phase === 'owned' && owned && <OwnedCard item={owned} onAgain={reset} />}
      {phase === 'missing' && checked && (
        <MissingIssue
          checked={checked}
          lookup={lookup}
          choice={choice}
          onChoice={setChoice}
          photo={photo}
          onPhoto={onPhoto}
          onSave={onSave}
          onCancel={reset}
          saving={saving}
        />
      )}
    </div>
  );
}

import { useCallback, useEffect, useState } from 'preact/hooks';
import { api } from './api.js';
import { CheckIssue } from './CheckIssue.jsx';
import { CollectionList } from './CollectionList.jsx';

const SERIES_STORAGE_KEY = 'comic-collection.series';

export function App() {
  const [view, setView] = useState('check');
  const [series, setSeries] = useState(() => localStorage.getItem(SERIES_STORAGE_KEY) ?? '');
  const [items, setItems] = useState([]);
  const [seriesNames, setSeriesNames] = useState([]);
  const [loadError, setLoadError] = useState('');
  const [toast, setToast] = useState('');

  const refresh = useCallback(async () => {
    try {
      const data = await api.list();
      setItems(data.items);
      setSeriesNames(data.series);
      setLoadError('');
    } catch (error) {
      setLoadError(error.message);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  useEffect(() => {
    localStorage.setItem(SERIES_STORAGE_KEY, series);
  }, [series]);

  useEffect(() => {
    if (!toast) return undefined;
    const timer = setTimeout(() => setToast(''), 4000);
    return () => clearTimeout(timer);
  }, [toast]);

  async function removeItem(item) {
    if (!window.confirm(`Remove ${item.series} #${item.number} from your collection?`)) return;
    try {
      await api.remove(item.id);
      setToast(`Removed ${item.series} #${item.number}`);
      refresh();
    } catch (error) {
      setLoadError(error.message);
    }
  }

  return (
    <div class="app">
      <header class="topbar">
        <h1>Comic Collection</h1>
        <button
          type="button"
          class="secondary"
          onClick={() => setView(view === 'check' ? 'collection' : 'check')}
        >
          {view === 'check' ? `My collection (${items.length})` : 'Check an issue'}
        </button>
      </header>

      <main>
        {loadError && (
          <p class="alert" role="alert">
            {loadError}
          </p>
        )}

        {view === 'check' ? (
          <CheckIssue
            series={series}
            onSeriesChange={setSeries}
            seriesOptions={seriesNames}
            onSaved={(item) => {
              setToast(`Added ${item.series} #${item.number} to your collection`);
              refresh();
            }}
          />
        ) : (
          <CollectionList items={items} onRemove={removeItem} />
        )}
      </main>

      <div class="toast" role="status" aria-live="polite">
        {toast}
      </div>
    </div>
  );
}

:root {
  --bg: #f5f1e8;
  --surface: #ffffff;
  --text: #1c1b1f;
  --muted: #5f5a66;
  --border: #d9d2c3;
  --primary: #1d4ed8;
  --primary-text: #ffffff;
  --danger: #b42318;
  --ok: #067647;
  --alert-bg: #fef3f2;
  --alert-text: #912018;
  --radius: 14px;
  color-scheme: light dark;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #15141a;
    --surface: #222029;
    --text: #f3f0f7;
    --muted: #b3adbd;
    --border: #3a3643;
    --primary: #5b8cff;
    --primary-text: #0b1020;
    --danger: #ff8a80;
    --ok: #6ce9a6;
    --alert-bg: #3a1d1b;
    --alert-text: #ffb4ab;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

h1,
h2,
h3 {
  margin: 0;
  line-height: 1.2;
}

h2 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

h3 {
  font-size: 1rem;
  margin: 1.25rem 0 0.5rem;
}

a {
  color: var(--primary);
}

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 0 1rem 6rem;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: calc(env(safe-area-inset-top) + 0.9rem) 0 0.9rem;
  background: var(--bg);
}

.topbar h1 {
  font-size: 1.35rem;
}

main {
  padding-top: 0.5rem;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  margin-top: 1rem;
}

.check-form {
  margin-top: 0;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 0.9rem;
  font-weight: 600;
}

.field small {
  font-weight: 400;
  color: var(--muted);
}

.field input {
  font: inherit;
  font-weight: 400;
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg);
  color: var(--text);
  width: 100%;
}

.field input:focus,
button:focus-visible,
.file-button:focus-within,
a:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--primary) 60%, transparent);
  outline-offset: 2px;
}

.row {
  display: flex;
  gap: 0.75rem;
}

.grow {
  flex: 1;
}

.year {
  width: 7.5rem;
}

button,
.button {
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  border-radius: 10px;
  padding: 0.7rem 1.1rem;
  border: 1px solid transparent;
  text-align: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
}

button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.primary {
  background: var(--primary);
  color: var(--primary-text);
  width: 100%;
}

.secondary,
.button.secondary {
  background: var(--surface);
  color: var(--primary);
  border-color: var(--border);
}

.ghost {
  background: transparent;
  color: var(--muted);
  border-color: var(--border);
}

.danger {
  color: var(--danger);
}

.file-button {
  cursor: pointer;
  position: relative;
  margin-top: 0.5rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.alert {
  background: var(--alert-bg);
  color: var(--alert-text);
  border-radius: 10px;
  padding: 0.75rem 1rem;
  margin: 1rem 0 0;
}

.muted {
  color: var(--muted);
}

.hint {
  font-size: 0.9rem;
  margin: 0.6rem 0 0;
}

.badge {
  display: inline-block;
  color: var(--ok);
  font-weight: 700;
  margin: 0 0 0.75rem;
}

.owned-body {
  display: flex;
  gap: 1rem;
  align-items: flex-start;
}

.owned-body img {
  width: 130px;
  flex: none;
  border-radius: 10px;
  border: 1px solid var(--border);
}

.owned-body h2 {
  margin-bottom: 0.4rem;
}

.owned .secondary {
  margin-top: 1rem;
  width: 100%;
}

.details {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 0.2rem;
  font-size: 0.95rem;
}

.sources {
  list-style: none;
  padding: 0;
  margin: 0 0 0.5rem;
  font-size: 0.9rem;
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 1rem;
}

.candidates {
  border: 0;
  padding: 0;
  margin: 0.5rem 0 0;
  display: grid;
  gap: 0.5rem;
}

.candidates legend {
  font-weight: 600;
  margin-bottom: 0.5rem;
  padding: 0;
}

.candidate {
  display: grid;
  grid-template-columns: auto 64px 1fr;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  cursor: pointer;
}

.candidate:has(input:checked) {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary);
}

.candidate.none {
  grid-template-columns: auto 1fr;
  color: var(--muted);
}

.candidate img,
.cover-placeholder {
  width: 64px;
  height: 90px;
  object-fit: cover;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg);
}

.cover-placeholder {
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  color: var(--muted);
  text-align: center;
}

.candidate-text {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font-size: 0.92rem;
  min-width: 0;
}

.candidate-text span {
  overflow-wrap: anywhere;
}

.preview {
  display: block;
  width: 100%;
  max-width: 320px;
  margin-top: 0.9rem;
  border-radius: 10px;
  border: 1px solid var(--border);
}

.actions {
  display: grid;
  gap: 0.5rem;
  margin-top: 1rem;
}

.collection {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 0.75rem;
}

.collection-item {
  display: grid;
  grid-template-columns: 72px 1fr auto;
  gap: 0.9rem;
  align-items: start;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.75rem;
}

.collection-item img {
  width: 72px;
  height: 100px;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid var(--border);
}

.collection-item h3 {
  margin: 0 0 0.35rem;
  font-size: 1.05rem;
}

.collection-item .ghost {
  padding: 0.45rem 0.7rem;
  font-size: 0.9rem;
}

.empty {
  margin: 0;
}

.toast {
  position: fixed;
  left: 50%;
  bottom: calc(env(safe-area-inset-bottom) + 1rem);
  transform: translateX(-50%);
  background: var(--text);
  color: var(--bg);
  padding: 0.7rem 1rem;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  max-width: calc(100% - 2rem);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.toast:not(:empty) {
  opacity: 1;
}

@media (min-width: 560px) {
  .actions {
    grid-template-columns: 1fr auto;
  }
}

// Renders the app icons (SVG + PNG) from one design using the Chromium that
// Playwright already installs for the end-to-end tests. Run with `npm run icons`.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outDir = path.join(root, 'client/public/icons');
const BLUE = '#1d4ed8';
const GOLD = '#f59e0b';

function iconSvg({ maskable = false } = {}) {
  const scale = maskable ? 0.72 : 1;
  const background = maskable
    ? `<rect width="512" height="512" fill="${BLUE}"/>`
    : `<rect width="512" height="512" rx="112" fill="${BLUE}"/>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">
  ${background}
  <g transform="translate(256 256) scale(${scale}) translate(-256 -256)">
    <rect x="124" y="96" width="264" height="330" rx="26" fill="#ffffff"/>
    <rect x="124" y="96" width="264" height="84" rx="26" fill="${GOLD}"/>
    <rect x="124" y="140" width="264" height="40" fill="${GOLD}"/>
    <text x="256" y="372" text-anchor="middle" font-family="Arial Black, Arial, sans-serif" font-weight="900" font-size="150" fill="${BLUE}">#1</text>
  </g>
</svg>
`;
}

const targets = [
  { file: 'icon-192.png', size: 192, svg: iconSvg() },
  { file: 'icon-512.png', size: 512, svg: iconSvg() },
  { file: 'icon-512-maskable.png', size: 512, svg: iconSvg({ maskable: true }) },
  { file: 'apple-touch-icon.png', size: 180, svg: iconSvg({ maskable: true }) },
];

fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'icon.svg'), iconSvg());

const browser = await chromium.launch();
try {
  const page = await browser.newPage({ deviceScaleFactor: 1 });
  for (const { file, size, svg } of targets) {
    await page.setViewportSize({ width: size, height: size });
    const sized = svg.replace('<svg ', `<svg width="${size}" height="${size}" `);
    await page.setContent(`<html><body style="margin:0;background:transparent">${sized}</body></html>`);
    await page.screenshot({ path: path.join(outDir, file), omitBackground: true, clip: { x: 0, y: 0, width: size, height: size } });
    console.log(`wrote ${path.join('client/public/icons', file)}`);
  }
} finally {
  await browser.close();
}

