// Generates the image fixtures used by the tests:
//   cover.png      – the "cover" that the stub comics.org API serves
//   comic-photo.jpg – a larger, photo-like picture a user would upload
// Run with `node tests/fixtures/make-fixture-images.mjs`.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const here = path.dirname(fileURLToPath(import.meta.url));

const drawCover = () => {
  const canvas = document.createElement('canvas');
  canvas.width = 400;
  canvas.height = 600;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#1d4ed8';
  ctx.fillRect(0, 0, 400, 600);
  ctx.fillStyle = '#f59e0b';
  ctx.fillRect(0, 0, 400, 150);
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 64px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('ASTÉRIX', 200, 98);
  ctx.beginPath();
  ctx.arc(200, 330, 120, 0, Math.PI * 2);
  ctx.fillStyle = '#fde68a';
  ctx.fill();
  ctx.fillStyle = '#1d4ed8';
  ctx.font = 'bold 120px Arial';
  ctx.fillText('5', 200, 380);
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 30px Arial';
  ctx.fillText('LE TOUR DE GAULE', 200, 520);
  return canvas.toDataURL('image/png');
};

const drawPhoto = () => {
  const canvas = document.createElement('canvas');
  canvas.width = 1200;
  canvas.height = 1600;
  const ctx = canvas.getContext('2d');
  const wood = ctx.createLinearGradient(0, 0, 1200, 1600);
  wood.addColorStop(0, '#8b5a2b');
  wood.addColorStop(1, '#4a2c12');
  ctx.fillStyle = wood;
  ctx.fillRect(0, 0, 1200, 1600);
  ctx.save();
  ctx.translate(600, 800);
  ctx.rotate(-0.06);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-380, -520, 760, 1040);
  ctx.fillStyle = '#dc2626';
  ctx.fillRect(-350, -490, 700, 980);
  ctx.fillStyle = '#fde047';
  ctx.beginPath();
  ctx.arc(0, -60, 230, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#111827';
  ctx.font = 'bold 200px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('5', 0, 150);
  ctx.font = 'bold 70px Arial';
  ctx.fillText('ASTÉRIX', 0, -330);
  ctx.restore();
  return canvas.toDataURL('image/jpeg', 0.92);
};

const browser = await chromium.launch();
try {
  const page = await browser.newPage();
  await page.setContent('<html><body></body></html>');
  const cover = await page.evaluate(`(${drawCover.toString()})()`);
  const photo = await page.evaluate(`(${drawPhoto.toString()})()`);
  fs.writeFileSync(path.join(here, 'cover.png'), Buffer.from(cover.split(',')[1], 'base64'));
  fs.writeFileSync(path.join(here, 'comic-photo.jpg'), Buffer.from(photo.split(',')[1], 'base64'));
  console.log('wrote tests/fixtures/cover.png and tests/fixtures/comic-photo.jpg');
} finally {
  await browser.close();
}

// A stand-in for the comics.org API used by the end-to-end tests, so they never
// depend on the live site. It mirrors the response shapes documented at
// https://www.comics.org/api/schema/redoc. Series named "Broken …" return HTTP 500.

import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.STUB_PORT || 4010);
const BASE = `http://localhost:${PORT}`;
const cover = fs.readFileSync(path.join(here, 'cover.png'));

const ISSUES = [
  { id: 273771, series: 'Astérix (1961 series)', number: '5', title: 'Le tour de Gaule', date: '1965', variantOf: null },
  { id: 2404546, series: 'Asterix (1968 series)', number: '5', title: 'Die goldene Sichel', date: '1971', variantOf: null },
  { id: 2404547, series: 'Asterix (1968 series)', number: '5', title: 'Die goldene Sichel (variant)', date: '1971', variantOf: 2404546 },
];

const normalize = (value) =>
  value.normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().trim();

function summary(issue) {
  return {
    api_url: `${BASE}/api/issue/${issue.id}/?format=json`,
    series_name: issue.series,
    descriptor: `${issue.number} - ${issue.title}`,
    publication_date: issue.date,
    price: '',
    page_count: null,
    variant_of: issue.variantOf ? `${BASE}/api/issue/${issue.variantOf}/?format=json` : null,
    series: `${BASE}/api/series/1/?format=json`,
  };
}

function detail(issue) {
  return {
    api_url: `${BASE}/api/issue/${issue.id}/?format=json`,
    series_name: issue.series,
    descriptor: `${issue.number} - ${issue.title}`,
    number: issue.number,
    title: issue.title,
    publication_date: issue.date,
    indicia_publisher: null,
    cover: `${BASE}/covers/${issue.id}.png`,
  };
}

function send(res, status, body, type = 'application/json') {
  res.writeHead(status, { 'Content-Type': type });
  res.end(type === 'application/json' ? JSON.stringify(body) : body);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, BASE);
  const seriesMatch = /^\/api\/series\/name\/([^/]+)\/issue\/([^/]+)\/(?:year\/(\d{4})\/)?$/.exec(url.pathname);

  if (url.pathname === '/health') return send(res, 200, { ok: true });

  if (url.pathname.startsWith('/covers/')) return send(res, 200, cover, 'image/png');

  if (seriesMatch) {
    const [, rawName, rawNumber, year] = seriesMatch;
    const name = normalize(decodeURIComponent(rawName));
    const number = decodeURIComponent(rawNumber);
    if (name.startsWith('broken')) return send(res, 500, { detail: 'stub failure' });

    const results = ISSUES.filter(
      (issue) =>
        normalize(issue.series).startsWith(name) &&
        issue.number === number &&
        (!year || issue.date === year),
    ).map(summary);
    return send(res, 200, { count: results.length, next: null, previous: null, results });
  }

  const issueMatch = /^\/api\/issue\/(\d+)\/$/.exec(url.pathname);
  if (issueMatch) {
    const issue = ISSUES.find((candidate) => candidate.id === Number(issueMatch[1]));
    return issue ? send(res, 200, detail(issue)) : send(res, 404, { detail: 'Not found.' });
  }

  return send(res, 404, { detail: 'Not found.' });
});

server.listen(PORT, () => {
  console.log(`Stub comics.org API on ${BASE}`);
});

// Starts the real app for the end-to-end tests: a fresh data directory, the small
// Inducks fixture imported into its own database, and the stub comics.org API
// configured through COMICS_ORG_API_URL (see playwright.config.js).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { importInducks } from '../../server/metadata/inducks-import.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');

if (!process.env.DATA_DIR || !process.env.INDUCKS_DB_PATH) {
  throw new Error('DATA_DIR and INDUCKS_DB_PATH must be set');
}

fs.rmSync(process.env.DATA_DIR, { recursive: true, force: true });
fs.rmSync(process.env.INDUCKS_DB_PATH, { force: true });
await importInducks({
  dir: path.join(root, 'tests/fixtures/inducks/isv'),
  dbPath: process.env.INDUCKS_DB_PATH,
});

await import('../../server/index.js');

import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { defineConfig, devices } from '@playwright/test';

const root = path.dirname(fileURLToPath(import.meta.url));
const APP_PORT = 4173;
const STUB_PORT = 4010;
const testData = path.join(root, 'tests/.tmp');

export default defineConfig({
  testDir: 'tests/e2e',
  testMatch: '**/*.spec.js',
  timeout: 60_000,
  fullyParallel: false,
  workers: 1,
  reporter: [['list']],
  use: {
    baseURL: `http://localhost:${APP_PORT}`,
    trace: 'retain-on-failure',
  },
  projects: [
    { name: 'phone', use: { ...devices['Pixel 7'] } },
    { name: 'desktop', use: { ...devices['Desktop Chrome'], viewport: { width: 1280, height: 900 } } },
  ],
  webServer: [
    {
      command: 'node tests/fixtures/stub-comics-org.js',
      url: `http://localhost:${STUB_PORT}/health`,
      reuseExistingServer: false,
      env: { STUB_PORT: String(STUB_PORT) },
    },
    {
      command: 'npm run build --silent && node tests/e2e/start-server.js',
      url: `http://localhost:${APP_PORT}/api/health`,
      reuseExistingServer: false,
      env: {
        PORT: String(APP_PORT),
        DATA_DIR: path.join(testData, 'data'),
        INDUCKS_DB_PATH: path.join(testData, 'inducks.sqlite'),
        COMICS_ORG_API_URL: `http://localhost:${STUB_PORT}/api`,
      },
    },
  ],
});

