// Package config loads runtime settings from environment variables.
package config

import (
	"errors"
	"fmt"
	"net/url"
	"path/filepath"
	"strconv"
	"strings"
)

const (
	defaultPort            = 3000
	defaultDataDir         = "data"
	defaultWebDir          = "dist"
	defaultComicsOrgAPIURL = "https://www.comics.org/api"
)

// Config holds every setting the server and tools read at startup.
type Config struct {
	Port               int
	DataDir            string
	WebDir             string
	CollectionDBPath   string
	PhotosDir          string
	InducksDBPath      string
	ComicsOrgAPIURL    string
	LogFormat          string
}

// Load reads the configuration using getenv, which is os.Getenv in production
// and a map lookup in tests. Relative paths are resolved against the working
// directory so the process behaves the same wherever it is started from.
func Load(getenv func(string) string) (Config, error) {
	cfg := Config{
		Port:            defaultPort,
		DataDir:         defaultDataDir,
		WebDir:          defaultWebDir,
		ComicsOrgAPIURL: defaultComicsOrgAPIURL,
		LogFormat:       "text",
	}

	if v := getenv("PORT"); v != "" {
		port, err := strconv.Atoi(v)
		if err != nil || port < 1 || port > 65535 {
			return Config{}, fmt.Errorf("PORT must be a number between 1 and 65535, got %q", v)
		}
		cfg.Port = port
	}
	if v := getenv("DATA_DIR"); v != "" {
		cfg.DataDir = v
	}
	if v := getenv("WEB_DIR"); v != "" {
		cfg.WebDir = v
	}
	if v := getenv("COMICS_ORG_API_URL"); v != "" {
		cfg.ComicsOrgAPIURL = v
	}
	if v := getenv("LOG_FORMAT"); v != "" {
		if v != "text" && v != "json" {
			return Config{}, fmt.Errorf("LOG_FORMAT must be text or json, got %q", v)
		}
		cfg.LogFormat = v
	}

	var err error
	if cfg.DataDir, err = filepath.Abs(cfg.DataDir); err != nil {
		return Config{}, fmt.Errorf("DATA_DIR: %w", err)
	}
	if cfg.WebDir, err = filepath.Abs(cfg.WebDir); err != nil {
		return Config{}, fmt.Errorf("WEB_DIR: %w", err)
	}

	cfg.CollectionDBPath = filepath.Join(cfg.DataDir, "collection.sqlite")
	cfg.PhotosDir = filepath.Join(cfg.DataDir, "photos")
	cfg.InducksDBPath = filepath.Join(cfg.DataDir, "inducks.sqlite")
	if v := getenv("INDUCKS_DB_PATH"); v != "" {
		if cfg.InducksDBPath, err = filepath.Abs(v); err != nil {
			return Config{}, fmt.Errorf("INDUCKS_DB_PATH: %w", err)
		}
	}

	cfg.ComicsOrgAPIURL = strings.TrimRight(cfg.ComicsOrgAPIURL, "/")
	u, err := url.Parse(cfg.ComicsOrgAPIURL)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
		return Config{}, errors.New("COMICS_ORG_API_URL must be an absolute http or https URL")
	}

	return cfg, nil
}

package config

import (
	"path/filepath"
	"testing"
)

func env(values map[string]string) func(string) string {
	return func(key string) string { return values[key] }
}

func TestLoadDefaults(t *testing.T) {
	cfg, err := Load(env(nil))
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	if cfg.Port != 3000 {
		t.Errorf("Port = %d, want 3000", cfg.Port)
	}
	if cfg.ComicsOrgAPIURL != "https://www.comics.org/api" {
		t.Errorf("ComicsOrgAPIURL = %q", cfg.ComicsOrgAPIURL)
	}
	if !filepath.IsAbs(cfg.CollectionDBPath) {
		t.Errorf("CollectionDBPath %q is not absolute", cfg.CollectionDBPath)
	}
	if filepath.Base(cfg.InducksDBPath) != "inducks.sqlite" {
		t.Errorf("InducksDBPath = %q", cfg.InducksDBPath)
	}
	if cfg.LogFormat != "text" {
		t.Errorf("LogFormat = %q, want text", cfg.LogFormat)
	}
}

func TestLoadOverrides(t *testing.T) {
	cfg, err := Load(env(map[string]string{
		"PORT":                "8080",
		"DATA_DIR":            "/srv/comics",
		"INDUCKS_DB_PATH":     "/srv/index/inducks.sqlite",
		"COMICS_ORG_API_URL":  "https://example.test/api/",
		"LOG_FORMAT":          "json",
	}))
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d", cfg.Port)
	}
	if cfg.CollectionDBPath != "/srv/comics/collection.sqlite" {
		t.Errorf("CollectionDBPath = %q", cfg.CollectionDBPath)
	}
	if cfg.PhotosDir != "/srv/comics/photos" {
		t.Errorf("PhotosDir = %q", cfg.PhotosDir)
	}
	if cfg.InducksDBPath != "/srv/index/inducks.sqlite" {
		t.Errorf("InducksDBPath = %q", cfg.InducksDBPath)
	}
	if cfg.ComicsOrgAPIURL != "https://example.test/api" {
		t.Errorf("ComicsOrgAPIURL = %q, want trailing slash trimmed", cfg.ComicsOrgAPIURL)
	}
	if cfg.LogFormat != "json" {
		t.Errorf("LogFormat = %q", cfg.LogFormat)
	}
}

func TestLoadRejectsInvalidValues(t *testing.T) {
	tests := map[string]map[string]string{
		"port not a number":   {"PORT": "http"},
		"port out of range":   {"PORT": "70000"},
		"unknown log format":  {"LOG_FORMAT": "yaml"},
		"relative api url":    {"COMICS_ORG_API_URL": "/api"},
		"non-http api scheme": {"COMICS_ORG_API_URL": "ftp://example.test/api"},
	}
	for name, values := range tests {
		t.Run(name, func(t *testing.T) {
			if _, err := Load(env(values)); err == nil {
				t.Fatal("Load() succeeded, want an error")
			}
		})
	}
}

// Package store opens the SQLite databases, applies schema migrations and
// provides the HTTP response cache shared by the metadata clients.
package store

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"path"
	"sort"
	"strconv"
	"strings"
	"time"

	_ "modernc.org/sqlite" // registers the pure-Go "sqlite" driver
)

//go:embed migrations/*.sql
var collectionMigrations embed.FS

// OpenCollection opens the collection database, creating it if needed, and
// applies any pending migrations. The database runs in WAL mode so the API can
// keep serving reads while a write is in progress.
func OpenCollection(ctx context.Context, file string) (*sql.DB, error) {
	db, err := sql.Open("sqlite", dsn(file,
		"_pragma=busy_timeout(5000)",
		"_pragma=foreign_keys(ON)",
		"_pragma=journal_mode(WAL)",
		"_txlock=immediate",
	))
	if err != nil {
		return nil, fmt.Errorf("open collection database: %w", err)
	}
	if err := db.PingContext(ctx); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("open collection database: %w", err)
	}
	if err := migrate(ctx, db, collectionMigrations, "migrations"); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("migrate collection database: %w", err)
	}
	return db, nil
}

// OpenReadOnly opens an existing database without allowing writes.
func OpenReadOnly(ctx context.Context, file string) (*sql.DB, error) {
	db, err := sql.Open("sqlite", dsn(file, "_pragma=busy_timeout(5000)", "_pragma=query_only(ON)"))
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", file, err)
	}
	if err := db.PingContext(ctx); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("open %s: %w", file, err)
	}
	return db, nil
}

func dsn(file string, params ...string) string {
	return "file:" + file + "?" + strings.Join(params, "&")
}

func migrate(ctx context.Context, db *sql.DB, fsys fs.FS, dir string) error {
	entries, err := fs.ReadDir(fsys, dir)
	if err != nil {
		return err
	}
	names := make([]string, 0, len(entries))
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".sql") {
			names = append(names, entry.Name())
		}
	}
	sort.Strings(names)

	var current int
	if err := db.QueryRowContext(ctx, "PRAGMA user_version").Scan(&current); err != nil {
		return err
	}
	for _, name := range names {
		version, err := versionOf(name)
		if err != nil {
			return err
		}
		if version <= current {
			continue
		}
		script, err := fs.ReadFile(fsys, path.Join(dir, name))
		if err != nil {
			return err
		}
		if err := apply(ctx, db, version, string(script)); err != nil {
			return fmt.Errorf("%s: %w", name, err)
		}
		current = version
	}
	return nil
}

func versionOf(name string) (int, error) {
	prefix, _, ok := strings.Cut(name, "_")
	if !ok {
		return 0, fmt.Errorf("migration %q must start with a version number", name)
	}
	version, err := strconv.Atoi(prefix)
	if err != nil {
		return 0, fmt.Errorf("migration %q must start with a version number", name)
	}
	return version, nil
}

func apply(ctx context.Context, db *sql.DB, version int, script string) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()
	if _, err := tx.ExecContext(ctx, script); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, fmt.Sprintf("PRAGMA user_version = %d", version)); err != nil {
		return err
	}
	return tx.Commit()
}

// Cache stores response bodies by key with the time they were fetched.
type Cache struct {
	db *sql.DB
}

// NewCache returns a cache backed by the collection database.
func NewCache(db *sql.DB) *Cache {
	return &Cache{db: db}
}

// Get returns the cached payload when it is younger than maxAge.
func (c *Cache) Get(ctx context.Context, key string, maxAge time.Duration) ([]byte, bool, error) {
	var payload []byte
	var fetchedAt int64
	err := c.db.QueryRowContext(ctx,
		`SELECT payload, fetched_at FROM http_cache WHERE cache_key = ?`, key,
	).Scan(&payload, &fetchedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, err
	}
	if time.Since(time.UnixMilli(fetchedAt)) > maxAge {
		return nil, false, nil
	}
	return payload, true, nil
}

// Put stores payload under key, replacing any previous entry.
func (c *Cache) Put(ctx context.Context, key string, payload []byte) error {
	_, err := c.db.ExecContext(ctx, `
		INSERT INTO http_cache (cache_key, payload, fetched_at) VALUES (?, ?, ?)
		ON CONFLICT (cache_key) DO UPDATE SET payload = excluded.payload, fetched_at = excluded.fetched_at`,
		key, payload, time.Now().UnixMilli())
	return err
}

// Package catalog holds the types shared by the metadata sources: the query
// a user makes and the candidate issues a source returns for it.
package catalog

// Source names. They are stored with saved issues and shown to users.
const (
	SourceComicsOrg = "comics.org"
	SourceInducks   = "inducks"
)

// Query identifies an issue by series name and issue number, optionally
// narrowed by publication year.
type Query struct {
	Series string
	Number string
	Year   string
}

// Candidate is one possible match for a Query, as reported by a source.
type Candidate struct {
	Source          string `json:"source"`
	SourceID        string `json:"sourceId"`
	SourceURL       string `json:"sourceUrl"`
	SeriesTitle     string `json:"seriesTitle"`
	Title           string `json:"title"`
	PublicationDate string `json:"publicationDate"`
	CoverURL        string `json:"coverUrl"`
}

