	"golang.org/x/text/runes"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// ErrNotFound is returned when an issue or its photo does not exist.
var ErrNotFound = errors.New("not found")

// ErrDuplicate is returned when the issue is already in the collection.
var ErrDuplicate = errors.New("this issue is already in the collection")

// DuplicateError carries the issue that is already stored.
type DuplicateError struct {
	Existing Comic
}

func (e *DuplicateError) Error() string { return ErrDuplicate.Error() }

// Unwrap lets callers match the error with errors.Is(err, ErrDuplicate).
func (e *DuplicateError) Unwrap() error { return ErrDuplicate }

// Comic is an issue in the collection.
type Comic struct {
	ID              int64
	Series          string
	Number          string
	Source          string
	SourceID        string
	SourceURL       string
	SeriesTitle     string
	Title           string
	PublicationDate string
	CoverURL        string
	PhotoFile       string
	CreatedAt       time.Time
}

// NewComic describes an issue to add. Match is nil when the user saved it
// without choosing a catalogue entry.
type NewComic struct {
	Series    string
	Number    string
	PhotoData []byte
	PhotoExt  string
	Match     *catalog.Candidate
}

// SeriesKey normalises a series name for comparison: case, accents and
// repeated whitespace are ignored.
func SeriesKey(series string) string {
	folded, _, err := transform.String(accentFolder, series)
	if err != nil {
		folded = series
	}
	return strings.Join(strings.Fields(strings.ToLower(folded)), " ")
}

var accentFolder = transform.Chain(norm.NFD, runes.Remove(runes.In(unicode.Mn)), norm.NFC)

// NumberKey normalises an issue number for comparison: whitespace is removed,
// letters are upper-cased and leading zeros are dropped, so "05" equals "5".
func NumberKey(number string) string {
	key := strings.ToUpper(strings.Join(strings.Fields(number), ""))
	for len(key) > 1 && key[0] == '0' && key[1] >= '0' && key[1] <= '9' {
		key = key[1:]
	}
	return key
}

// Store persists the collection in SQLite and photos on disk.
type Store struct {
	db        *sql.DB
	photosDir string
}

// NewStore returns a Store that keeps photos in photosDir.
func NewStore(db *sql.DB, photosDir string) *Store {
	return &Store{db: db, photosDir: photosDir}
}

const selectColumns = `id, series, number,
	COALESCE(source, ''), COALESCE(source_id, ''), COALESCE(source_url, ''),
	COALESCE(series_title, ''), COALESCE(title, ''), COALESCE(publication_date, ''),
	COALESCE(cover_url, ''), photo_file, created_at`

// List returns every issue ordered by series, then numerically by issue number.
func (s *Store) List(ctx context.Context) ([]Comic, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT `+selectColumns+`
		FROM comics ORDER BY series_key, CAST(number_key AS INTEGER), number_key`)
	if err != nil {
		return nil, fmt.Errorf("list collection: %w", err)
	}
	defer func() { _ = rows.Close() }()

	var comics []Comic
	for rows.Next() {
		comic, err := scanComic(rows)
		if err != nil {
			return nil, fmt.Errorf("list collection: %w", err)
		}
		comics = append(comics, comic)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list collection: %w", err)
	}
	return comics, nil
}

// SeriesNames returns the distinct series names in the collection.
func (s *Store) SeriesNames(ctx context.Context) ([]string, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT DISTINCT series FROM comics ORDER BY series`)
	if err != nil {
		return nil, fmt.Errorf("list series: %w", err)
	}
	defer func() { _ = rows.Close() }()

	var names []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, fmt.Errorf("list series: %w", err)
		}
		names = append(names, name)
	}
	return names, rows.Err()
}

// Find returns the issue matching series and number, or ErrNotFound.
func (s *Store) Find(ctx context.Context, series, number string) (Comic, error) {
	return findByKey(ctx, s.db, SeriesKey(series), NumberKey(number))
}

// Get returns the issue with the given id, or ErrNotFound.
func (s *Store) Get(ctx context.Context, id int64) (Comic, error) {
	row := s.db.QueryRowContext(ctx, `SELECT `+selectColumns+` FROM comics WHERE id = ?`, id)
	comic, err := scanComic(row)
	if errors.Is(err, sql.ErrNoRows) {
		return Comic{}, ErrNotFound
	}
	return comic, err
}

// PhotoPath returns the absolute path of the issue's photo, or ErrNotFound.
func (s *Store) PhotoPath(ctx context.Context, id int64) (string, error) {
	comic, err := s.Get(ctx, id)
	if err != nil {
		return "", err
	}
	return filepath.Join(s.photosDir, comic.PhotoFile), nil
}

// Add stores a new issue and its photo. It returns *DuplicateError when the
// issue is already present; the existing issue is included in the error.
func (s *Store) Add(ctx context.Context, in NewComic) (Comic, error) {
	seriesKey, numberKey := SeriesKey(in.Series), NumberKey(in.Number)
	photoFile, err := newPhotoFileName(in.PhotoExt)
	if err != nil {
		return Comic{}, err
	}

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return Comic{}, fmt.Errorf("add to collection: %w", err)
	}
	defer func() { _ = tx.Rollback() }()

	existing, err := findByKey(ctx, tx, seriesKey, numberKey)
	switch {
	case err == nil:
		return Comic{}, &DuplicateError{Existing: existing}
	case !errors.Is(err, ErrNotFound):
		return Comic{}, fmt.Errorf("add to collection: %w", err)
	}

	result, err := tx.ExecContext(ctx, `
		INSERT INTO comics (series, series_key, number, number_key, source, source_id, source_url,
			series_title, title, publication_date, cover_url, photo_file, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		in.Series, seriesKey, in.Number, numberKey,
		matchField(in.Match, func(c *catalog.Candidate) string { return c.Source }),
		matchField(in.Match, func(c *catalog.Candidate) string { return c.SourceID }),
		matchField(in.Match, func(c *catalog.Candidate) string { return c.SourceURL }),
		matchField(in.Match, func(c *catalog.Candidate) string { return c.SeriesTitle }),
		matchField(in.Match, func(c *catalog.Candidate) string { return c.Title }),
		matchField(in.Match, func(c *catalog.Candidate) string { return c.PublicationDate }),
		matchField(in.Match, func(c *catalog.Candidate) string { return c.CoverURL }),
		photoFile,
		time.Now().UTC().Format(time.RFC3339Nano),
	)
	if err != nil {
		return Comic{}, fmt.Errorf("add to collection: %w", err)
	}
	id, err := result.LastInsertId()
	if err != nil {
		return Comic{}, fmt.Errorf("add to collection: %w", err)
	}

	photoPath := filepath.Join(s.photosDir, photoFile)
	if err := writeFileAtomic(photoPath, in.PhotoData); err != nil {
		return Comic{}, fmt.Errorf("save photo: %w", err)
	}
	if err := tx.Commit(); err != nil {
		_ = os.Remove(photoPath)
		return Comic{}, fmt.Errorf("add to collection: %w", err)
	}
	return s.Get(ctx, id)
}

// Remove deletes the issue and its photo. It returns ErrNotFound when the
// issue does not exist.
func (s *Store) Remove(ctx context.Context, id int64) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("remove from collection: %w", err)
	}
	defer func() { _ = tx.Rollback() }()

	var photoFile string
	err = tx.QueryRowContext(ctx, `SELECT photo_file FROM comics WHERE id = ?`, id).Scan(&photoFile)
	if errors.Is(err, sql.ErrNoRows) {
		return ErrNotFound
	}
	if err != nil {
		return fmt.Errorf("remove from collection: %w", err)
	}
	if _, err := tx.ExecContext(ctx, `DELETE FROM comics WHERE id = ?`, id); err != nil {
		return fmt.Errorf("remove from collection: %w", err)
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("remove from collection: %w", err)
	}
	if err := os.Remove(filepath.Join(s.photosDir, photoFile)); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("remove photo: %w", err)
	}
	return nil
}

type rowQuerier interface {
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
}

func findByKey(ctx context.Context, q rowQuerier, seriesKey, numberKey string) (Comic, error) {
	row := q.QueryRowContext(ctx,
		`SELECT `+selectColumns+` FROM comics WHERE series_key = ? AND number_key = ?`,
		seriesKey, numberKey)
	comic, err := scanComic(row)
	if errors.Is(err, sql.ErrNoRows) {
		return Comic{}, ErrNotFound
	}
	return comic, err
}

type scanner interface {
	Scan(dest ...any) error
}

func scanComic(row scanner) (Comic, error) {
	var comic Comic
	var createdAt string
	err := row.Scan(
		&comic.ID, &comic.Series, &comic.Number,
		&comic.Source, &comic.SourceID, &comic.SourceURL,
		&comic.SeriesTitle, &comic.Title, &comic.PublicationDate,
		&comic.CoverURL, &comic.PhotoFile, &createdAt,
	)
	if err != nil {
		return Comic{}, err
	}
	comic.CreatedAt, err = time.Parse(time.RFC3339Nano, createdAt)
	if err != nil {
		return Comic{}, fmt.Errorf("parse created_at %q: %w", createdAt, err)
	}
	return comic, nil
}

func matchField(match *catalog.Candidate, pick func(*catalog.Candidate) string) string {
	if match == nil {
		return ""
	}
	return pick(match)
}

func newPhotoFileName(ext string) (string, error) {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("generate photo name: %w", err)
	}
	return hex.EncodeToString(buf) + "." + ext, nil
}

// writeFileAtomic writes to a temporary file and renames it into place, so a
// crash never leaves a half-written photo under its final name.
func writeFileAtomic(name string, data []byte) error {
	dir := filepath.Dir(name)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, ".upload-*")
	if err != nil {
		return err
	}
	defer func() { _ = os.Remove(tmp.Name()) }()

	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), name)
}

package collection

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/angelospillos/haiku-pwa/internal/catalog"
	"github.com/angelospillos/haiku-pwa/internal/store"
)

func TestSeriesKey(t *testing.T) {
	tests := map[string]string{
		"Asterix":        "asterix",
		"  ASTÉRIX  ":    "asterix",
		"Astérix\u00a0 x": "asterix x",
		"Topolino (libretto)": "topolino (libretto)",
	}
	for in, want := range tests {
		if got := SeriesKey(in); got != want {
			t.Errorf("SeriesKey(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestNumberKey(t *testing.T) {
	tests := map[string]string{
		"5":       "5",
		"05":      "5",
		" 5 ":     "5",
		"00":      "0",
		"0A":      "0A",
		"12a":     "12A",
		"2001-03": "2001-03",
	}
	for in, want := range tests {
		if got := NumberKey(in); got != want {
			t.Errorf("NumberKey(%q) = %q, want %q", in, got, want)
		}
	}
}

func openStore(t *testing.T) (*Store, string) {
	t.Helper()
	dir := t.TempDir()
	db, err := store.OpenCollection(context.Background(), filepath.Join(dir, "collection.sqlite"))
	if err != nil {
		t.Fatalf("OpenCollection() error = %v", err)
	}
	t.Cleanup(func() { _ = db.Close() })
	photos := filepath.Join(dir, "photos")
	return NewStore(db, photos), photos
}

func photo() NewComic {
	return NewComic{Series: "Asterix", Number: "5", PhotoData: []byte("jpeg-bytes"), PhotoExt: "jpg"}
}

func TestAddFindAndRemove(t *testing.T) {
	ctx := context.Background()
	s, photosDir := openStore(t)

	comic, err := s.Add(ctx, photo())
	if err != nil {
		t.Fatalf("Add() error = %v", err)
	}
	if comic.Series != "Asterix" || comic.Number != "5" {
		t.Errorf("saved %q #%q", comic.Series, comic.Number)
	}

	found, err := s.Find(ctx, "ASTERIX ", "05")
	if err != nil {
		t.Fatalf("Find() error = %v", err)
	}
	if found.ID != comic.ID {
		t.Errorf("Find() id = %d, want %d", found.ID, comic.ID)
	}

	photoPath, err := s.PhotoPath(ctx, comic.ID)
	if err != nil {
		t.Fatalf("PhotoPath() error = %v", err)
	}
	if filepath.Dir(photoPath) != photosDir {
		t.Errorf("photo stored in %q, want %q", filepath.Dir(photoPath), photosDir)
	}
	if _, err := os.Stat(photoPath); err != nil {
		t.Fatalf("photo file missing: %v", err)
	}

	if err := s.Remove(ctx, comic.ID); err != nil {
		t.Fatalf("Remove() error = %v", err)
	}
	if _, err := s.Find(ctx, "Asterix", "5"); !errors.Is(err, ErrNotFound) {
		t.Errorf("Find() after Remove error = %v, want ErrNotFound", err)
	}
	if _, err := os.Stat(photoPath); !errors.Is(err, os.ErrNotExist) {
		t.Errorf("photo still exists after Remove: %v", err)
	}
	if err := s.Remove(ctx, comic.ID); !errors.Is(err, ErrNotFound) {
		t.Errorf("second Remove() error = %v, want ErrNotFound", err)
	}
}

func TestAddRejectsDuplicateAndReturnsExisting(t *testing.T) {
	ctx := context.Background()
	s, _ := openStore(t)

	first, err := s.Add(ctx, photo())
	if err != nil {
		t.Fatalf("Add() error = %v", err)
	}

	dup := photo()
	dup.Series = "asterix"
	dup.Number = "05"
	_, err = s.Add(ctx, dup)
	if !errors.Is(err, ErrDuplicate) {
		t.Fatalf("Add() duplicate error = %v, want ErrDuplicate", err)
	}
	var dupErr *DuplicateError
	if !errors.As(err, &dupErr) || dupErr.Existing.ID != first.ID {
		t.Errorf("DuplicateError.Existing = %+v, want id %d", dupErr, first.ID)
	}
}

func TestAddStoresCatalogueDetails(t *testing.T) {
	ctx := context.Background()
	s, _ := openStore(t)

	in := NewComic{
		Series:    "Topolino",
		Number:    "3401",
		PhotoData: []byte("bytes"),
		PhotoExt:  "jpg",
		Match: &catalog.Candidate{
			Source:          catalog.SourceInducks,
			SourceID:        "it/TL 3401",
			SourceURL:       "https://inducks.org/issue.php?c=it%2FTL+3401",
			SeriesTitle:     "Topolino (libretto) · Italy",
			PublicationDate: "2021-01-27",
		},
	}
	comic, err := s.Add(ctx, in)
	if err != nil {
		t.Fatalf("Add() error = %v", err)
	}
	if comic.Source != catalog.SourceInducks || comic.PublicationDate != "2021-01-27" {
		t.Errorf("saved details = %+v", comic)
	}
}

func TestAddWithoutMatchLeavesDetailsEmpty(t *testing.T) {
	ctx := context.Background()
	s, _ := openStore(t)

	comic, err := s.Add(ctx, photo())
	if err != nil {
		t.Fatalf("Add() error = %v", err)
	}
	if comic.Source != "" || comic.SourceURL != "" || comic.Title != "" {
		t.Errorf("expected no catalogue details, got %+v", comic)
	}
}

func TestListOrdersBySeriesThenNumericIssue(t *testing.T) {
	ctx := context.Background()
	s, _ := openStore(t)

	for _, number := range []string{"10", "2", "1"} {
		in := photo()
		in.Series = "Zeta"
		in.Number = number
		if _, err := s.Add(ctx, in); err != nil {
			t.Fatalf("Add(%s) error = %v", number, err)
		}
	}
	comics, err := s.List(ctx)
	if err != nil {
		t.Fatalf("List() error = %v", err)
	}
	var got []string
	for _, c := range comics {
		got = append(got, c.Number)
	}
	want := []string{"1", "2", "10"}
	if len(got) != len(want) {
		t.Fatalf("List() numbers = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("List() numbers = %v, want %v", got, want)
		}
	}
}

// Package photo validates the cover photos users upload.
package photo

import (
	"encoding/base64"
	"errors"
	"fmt"
	"net/http"
	"strings"
)

// MaxBytes is the largest decoded photo accepted.
const MaxBytes = 10 << 20

var (
	// ErrUnsupported is returned for anything that is not a JPEG, PNG or WebP image.
	ErrUnsupported = errors.New("a photo of the comic is required (JPEG, PNG or WebP)")
	// ErrTooLarge is returned when the decoded photo exceeds MaxBytes.
	ErrTooLarge = errors.New("photo is too large (10 MB limit)")
	// ErrInvalid is returned when the data URL cannot be decoded.
	ErrInvalid = errors.New("photo data is not valid base64")
)

// Photo is a validated image ready to be stored.
type Photo struct {
	Data        []byte
	Extension   string
	ContentType string
}

var extensions = map[string]string{
	"image/jpeg": "jpg",
	"image/png":  "png",
	"image/webp": "webp",
}

// ParseDataURL decodes a base64 data URL such as the one a browser produces
// from a canvas. The image type is decided by sniffing the bytes, so a
// mislabelled file is rejected.
func ParseDataURL(dataURL string) (Photo, error) {
	header, payload, ok := strings.Cut(dataURL, ",")
	if !ok || !strings.HasPrefix(header, "data:") || !strings.HasSuffix(header, ";base64") {
		return Photo{}, ErrUnsupported
	}
	declared := strings.TrimSuffix(strings.TrimPrefix(header, "data:"), ";base64")
	if _, ok := extensions[declared]; !ok {
		return Photo{}, ErrUnsupported
	}

	// Each base64 character carries six bits, so this bounds the decoded size
	// before any large allocation happens.
	if len(payload)/4*3 > MaxBytes {
		return Photo{}, ErrTooLarge
	}
	data, err := base64.StdEncoding.DecodeString(strings.Join(strings.Fields(payload), ""))
	if err != nil {
		return Photo{}, fmt.Errorf("%w: %v", ErrInvalid, err)
	}
	if len(data) == 0 {
		return Photo{}, ErrUnsupported
	}
	if len(data) > MaxBytes {
		return Photo{}, ErrTooLarge
	}

	sniffed := http.DetectContentType(data[:min(len(data), 512)])
	ext, ok := extensions[sniffed]
	if !ok {
		return Photo{}, ErrUnsupported
	}
	return Photo{Data: data, Extension: ext, ContentType: sniffed}, nil
}

package photo

import (
	"bytes"
	"encoding/base64"
	"errors"
	"image"
	"image/color"
	"image/jpeg"
	"image/png"
	"strings"
	"testing"
)

func dataURL(mime string, data []byte) string {
	return "data:" + mime + ";base64," + base64.StdEncoding.EncodeToString(data)
}

func solidImage(t *testing.T) *image.RGBA {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, 4, 4))
	for x := range 4 {
		for y := range 4 {
			img.Set(x, y, color.RGBA{R: 200, G: 30, B: 30, A: 255})
		}
	}
	return img
}

func TestParseDataURLAcceptsSupportedImages(t *testing.T) {
	var jpgBuf, pngBuf bytes.Buffer
	if err := jpeg.Encode(&jpgBuf, solidImage(t), nil); err != nil {
		t.Fatal(err)
	}
	if err := png.Encode(&pngBuf, solidImage(t)); err != nil {
		t.Fatal(err)
	}
	webp := append([]byte("RIFF\x10\x00\x00\x00WEBPVP8 "), make([]byte, 16)...)

	tests := []struct {
		name string
		url  string
		ext  string
	}{
		{"jpeg", dataURL("image/jpeg", jpgBuf.Bytes()), "jpg"},
		{"png", dataURL("image/png", pngBuf.Bytes()), "png"},
		{"webp", dataURL("image/webp", webp), "webp"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParseDataURL(tt.url)
			if err != nil {
				t.Fatalf("ParseDataURL() error = %v", err)
			}
			if got.Extension != tt.ext {
				t.Errorf("Extension = %q, want %q", got.Extension, tt.ext)
			}
			if len(got.Data) == 0 {
				t.Error("Data is empty")
			}
		})
	}
}

func TestParseDataURLRejectsWhatItCannotStore(t *testing.T) {
	var pngBuf bytes.Buffer
	if err := png.Encode(&pngBuf, solidImage(t)); err != nil {
		t.Fatal(err)
	}

	tests := map[string]struct {
		url     string
		wantErr error
	}{
		"not a data url":        {"https://example.test/a.jpg", ErrUnsupported},
		"plain text mime":       {dataURL("text/plain", []byte("hi")), ErrUnsupported},
		"image labelled as gif": {dataURL("image/gif", pngBuf.Bytes()), ErrUnsupported},
		"png labelled as jpeg":  {dataURL("image/jpeg", []byte("not an image at all")), ErrUnsupported},
		"empty payload":         {"data:image/jpeg;base64,", ErrUnsupported},
		"bad base64":            {"data:image/png;base64,@@@@", ErrInvalid},
		"too large":             {"data:image/jpeg;base64," + strings.Repeat("A", MaxBytes/3*4+8), ErrTooLarge},
	}
	for name, tt := range tests {
		t.Run(name, func(t *testing.T) {
			_, err := ParseDataURL(tt.url)
			if !errors.Is(err, tt.wantErr) {
				t.Fatalf("ParseDataURL() error = %v, want %v", err, tt.wantErr)
			}
		})
	}
}

