// Package inducks searches the Inducks index of Disney comics. Inducks blocks
// automated access to its website, so the index is built from the official
// daily data dump by Import instead.
package inducks

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"io/fs"
	"net/url"
	"os"
	"strings"

	"github.com/angelospillos/haiku-pwa/internal/catalog"
	"github.com/angelospillos/haiku-pwa/internal/store"
)

const maxCandidates = 20

// ErrNotSynced is returned by Open when the index file does not exist yet.
var ErrNotSynced = errors.New("inducks index not found")

// Index is a read-only view of the SQLite index built by Import.
type Index struct {
	db       *sql.DB
	syncedAt string
}

// Open opens the index at file. It returns ErrNotSynced when the file is missing.
func Open(ctx context.Context, file string) (*Index, error) {
	if _, err := os.Stat(file); errors.Is(err, fs.ErrNotExist) {
		return nil, ErrNotSynced
	}
	db, err := store.OpenReadOnly(ctx, file)
	if err != nil {
		return nil, err
	}
	index := &Index{db: db}
	_ = db.QueryRowContext(ctx, `SELECT value FROM meta WHERE key = 'synced_at'`).Scan(&index.syncedAt)
	return index, nil
}

// SyncedAt reports when the index was built, as an RFC 3339 timestamp.
func (i *Index) SyncedAt() string {
	if i == nil {
		return ""
	}
	return i.syncedAt
}

// Close releases the database handle. It is safe to call on a nil Index.
func (i *Index) Close() error {
	if i == nil {
		return nil
	}
	return i.db.Close()
}

const searchSQL = `
SELECT i.issuecode,
       COALESCE(i.title, ''),
       COALESCE(i.oldestdate, ''),
       p.title,
       COALESCE(c.countryname, '')
FROM issue i
JOIN publication p ON p.publicationcode = i.publicationcode
LEFT JOIN country c ON c.countrycode = p.countrycode
WHERE i.issuenumber = ?
  AND (
    p.title LIKE ? ESCAPE '\'
    OR p.publicationcode IN (
      SELECT publicationcode FROM publication_name WHERE publicationname LIKE ? ESCAPE '\'
    )
  )
  AND (? = '' OR i.oldestdate IS NULL OR i.oldestdate = '' OR substr(i.oldestdate, 1, 4) = ?)
ORDER BY (p.title LIKE ? ESCAPE '\') DESC, p.title, i.oldestdate
LIMIT ?`

// Search returns the issues whose publication name contains q.Series and whose
// issue number equals q.Number. A nil Index reports that the data is not synced.
func (i *Index) Search(ctx context.Context, q catalog.Query) ([]catalog.Candidate, error) {
	if i == nil {
		return nil, &catalog.UnavailableError{Source: catalog.SourceInducks, Reason: "has not been synced yet (run make sync)"}
	}

	term := escapeLike(q.Series)
	contains := "%" + term + "%"
	rows, err := i.db.QueryContext(ctx, searchSQL,
		q.Number, contains, contains, q.Year, q.Year, term+"%", maxCandidates)
	if err != nil {
		return nil, fmt.Errorf("search inducks: %w", err)
	}
	defer func() { _ = rows.Close() }()

	var candidates []catalog.Candidate
	for rows.Next() {
		var code, issueTitle, oldestDate, publicationTitle, country string
		if err := rows.Scan(&code, &issueTitle, &oldestDate, &publicationTitle, &country); err != nil {
			return nil, fmt.Errorf("search inducks: %w", err)
		}
		seriesTitle := publicationTitle
		if country != "" {
			seriesTitle += " · " + country
		}
		candidates = append(candidates, catalog.Candidate{
			Source:          catalog.SourceInducks,
			SourceID:        code,
			SourceURL:       "https://inducks.org/issue.php?" + url.Values{"c": {code}}.Encode(),
			SeriesTitle:     catalog.CleanText(seriesTitle, 200),
			Title:           catalog.CleanText(issueTitle, 200),
			PublicationDate: oldestDate,
		})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("search inducks: %w", err)
	}
	return candidates, nil
}

var likeEscaper = strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`)

func escapeLike(value string) string {
	return likeEscaper.Replace(value)
}

package inducks

import (
	"bufio"
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/angelospillos/haiku-pwa/internal/store"
)

// Members lists the files from the Inducks dump (isv/ inside isv.tgz) that the
// index needs. The rest of the dump is ignored.
var Members = []string{
	"inducks_issue.isv",
	"inducks_publication.isv",
	"inducks_publicationname.isv",
	"inducks_countryname.isv",
}

const maxLineBytes = 1 << 20

var schema = []string{
	`CREATE TABLE country (countrycode TEXT PRIMARY KEY, countryname TEXT NOT NULL)`,
	`CREATE TABLE publication (publicationcode TEXT PRIMARY KEY, countrycode TEXT, title TEXT NOT NULL)`,
	`CREATE TABLE publication_name (publicationcode TEXT NOT NULL, publicationname TEXT NOT NULL)`,
	`CREATE TABLE issue (
		issuecode TEXT PRIMARY KEY,
		publicationcode TEXT NOT NULL,
		issuenumber TEXT NOT NULL,
		title TEXT,
		oldestdate TEXT
	)`,
	`CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)`,
}

var indexes = []string{
	`CREATE INDEX issue_number ON issue (issuenumber)`,
	`CREATE INDEX publication_name_code ON publication_name (publicationcode)`,
}

// Counts reports how many rows an import stored.
type Counts struct {
	Countries        int
	Publications     int
	PublicationNames int
	Issues           int
}

// Import builds the index at dbPath from the .isv files in dir. The index is
// written to a temporary file and renamed into place only after the whole
// import succeeds, so readers never see a partial index.
func Import(ctx context.Context, dir, dbPath string) (Counts, error) {
	if err := os.MkdirAll(filepath.Dir(dbPath), 0o750); err != nil {
		return Counts{}, fmt.Errorf("create data directory: %w", err)
	}
	tmpPath := dbPath + ".tmp"
	_ = os.Remove(tmpPath)

	db, err := store.Create(ctx, tmpPath)
	if err != nil {
		return Counts{}, err
	}
	counts, err := build(ctx, db, dir)
	closeErr := db.Close()
	if err != nil {
		_ = os.Remove(tmpPath)
		return Counts{}, err
	}
	if closeErr != nil {
		_ = os.Remove(tmpPath)
		return Counts{}, fmt.Errorf("close index: %w", closeErr)
	}
	if err := os.Rename(tmpPath, dbPath); err != nil {
		_ = os.Remove(tmpPath)
		return Counts{}, fmt.Errorf("install index: %w", err)
	}
	return counts, nil
}

func build(ctx context.Context, db dbExecutor, dir string) (Counts, error) {
	for _, stmt := range schema {
		if _, err := db.ExecContext(ctx, stmt); err != nil {
			return Counts{}, fmt.Errorf("create schema: %w", err)
		}
	}

	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return Counts{}, err
	}
	defer func() { _ = tx.Rollback() }()

	var counts Counts
	if err := importCountries(ctx, tx, dir, &counts); err != nil {
		return Counts{}, err
	}
	if err := importPublications(ctx, tx, dir, &counts); err != nil {
		return Counts{}, err
	}
	if err := importPublicationNames(ctx, tx, dir, &counts); err != nil {
		return Counts{}, err
	}
	if err := importIssues(ctx, tx, dir, &counts); err != nil {
		return Counts{}, err
	}

	meta := map[string]string{
		"synced_at":    time.Now().UTC().Format(time.RFC3339),
		"issues":       fmt.Sprint(counts.Issues),
		"publications": fmt.Sprint(counts.Publications),
	}
	for key, value := range meta {
		if _, err := tx.ExecContext(ctx, `INSERT INTO meta (key, value) VALUES (?, ?)`, key, value); err != nil {
			return Counts{}, err
		}
	}
	if err := tx.Commit(); err != nil {
		return Counts{}, err
	}
	for _, stmt := range indexes {
		if _, err := db.ExecContext(ctx, stmt); err != nil {
			return Counts{}, fmt.Errorf("create index: %w", err)
		}
	}
	return counts, nil
}

type dbExecutor interface {
	ExecContext(ctx context.Context, query string, args ...any) (sqlResult, error)
	BeginTx(ctx context.Context, opts any) (txExecutor, error)
}

func importCountries(ctx context.Context, tx txExecutor, dir string, counts *Counts) error {
	stmt, err := tx.PrepareContext(ctx, `INSERT OR IGNORE INTO country (countrycode, countryname) VALUES (?, ?)`)
	if err != nil {
		return err
	}
	defer func() { _ = stmt.Close() }()
	return forEachRow(ctx, dir, "inducks_countryname.isv", func(f []string) error {
		if len(f) < 3 || f[1] != "en" || f[0] == "" || f[2] == "" {
			return nil
		}
		if _, err := stmt.ExecContext(ctx, f[0], f[2]); err != nil {
			return err
		}
		counts.Countries++
		return nil
	})
}

func importPublications(ctx context.Context, tx txExecutor, dir string, counts *Counts) error {
	stmt, err := tx.PrepareContext(ctx, `INSERT OR IGNORE INTO publication (publicationcode, countrycode, title) VALUES (?, ?, ?)`)
	if err != nil {
		return err
	}
	defer func() { _ = stmt.Close() }()
	return forEachRow(ctx, dir, "inducks_publication.isv", func(f []string) error {
		if len(f) < 4 || f[0] == "" || f[3] == "" {
			return nil
		}
		if _, err := stmt.ExecContext(ctx, f[0], f[1], f[3]); err != nil {
			return err
		}
		counts.Publications++
		return nil
	})
}

func importPublicationNames(ctx context.Context, tx txExecutor, dir string, counts *Counts) error {
	stmt, err := tx.PrepareContext(ctx, `INSERT INTO publication_name (publicationcode, publicationname) VALUES (?, ?)`)
	if err != nil {
		return err
	}
	defer func() { _ = stmt.Close() }()
	return forEachRow(ctx, dir, "inducks_publicationname.isv", func(f []string) error {
		if len(f) < 2 || f[0] == "" || f[1] == "" {
			return nil
		}
		if _, err := stmt.ExecContext(ctx, f[0], f[1]); err != nil {
			return err
		}
		counts.PublicationNames++
		return nil
	})
}

func importIssues(ctx context.Context, tx txExecutor, dir string, counts *Counts) error {
	stmt, err := tx.PrepareContext(ctx, `INSERT OR IGNORE INTO issue (issuecode, publicationcode, issuenumber, title, oldestdate) VALUES (?, ?, ?, ?, ?)`)
	if err != nil {
		return err
	}
	defer func() { _ = stmt.Close() }()
	return forEachRow(ctx, dir, "inducks_issue.isv", func(f []string) error {
		// Columns: issuecode, issuerangecode, publicationcode, issuenumber, title,
		// size, pages, price, printrun, attached, oldestdate, ...
		if len(f) < 11 || f[0] == "" || f[2] == "" || f[3] == "" {
			return nil
		}
		oldest := f[10]
		if oldest == "" || strings.HasPrefix(oldest, "9999") {
			oldest = ""
		}
		if _, err := stmt.ExecContext(ctx, f[0], f[2], f[3], f[4], oldest); err != nil {
			return err
		}
		counts.Issues++
		return nil
	})
}

// forEachRow calls fn with the ^-separated fields of every data row in dir/name.
// The first line of each .isv file is a header and is skipped. Rows that cannot
// be parsed, such as continuation lines of multi-line comments, are passed to fn
// with fewer fields and are ignored by the callers.
func forEachRow(ctx context.Context, dir, name string, fn func(fields []string) error) error {
	file, err := os.Open(filepath.Join(dir, name))
	if err != nil {
		return fmt.Errorf("open %s: %w", name, err)
	}
	defer func() { _ = file.Close() }()

	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 0, 64*1024), maxLineBytes)
	header := true
	for scanner.Scan() {
		if err := ctx.Err(); err != nil {
			return err
		}
		if header {
			header = false
			continue
		}
		line := scanner.Text()
		if line == "" {
			continue
		}
		if err := fn(strings.Split(line, "^")); err != nil {
			return fmt.Errorf("import %s: %w", name, err)
		}
	}
	if err := scanner.Err(); err != nil {
		return fmt.Errorf("read %s: %w", name, err)
	}
	return nil
}

