// Package lookup asks every metadata source for an issue at the same time and
// reports each source's outcome, so one failing source never hides the others.
package lookup

import (
	"context"
	"errors"
	"log/slog"
	"sync"

	"github.com/angelospillos/haiku-pwa/internal/catalog"
)

// Searcher is implemented by every metadata source.
type Searcher interface {
	Search(ctx context.Context, q catalog.Query) ([]catalog.Candidate, error)
}

// Source pairs a Searcher with the name it is reported under.
type Source struct {
	Name     string
	Searcher Searcher
}

// Status is the outcome of one source for one lookup.
type Status struct {
	OK      bool
	Count   int
	Message string
}

// Result is the combined answer to a lookup.
type Result struct {
	Query      catalog.Query
	Candidates []catalog.Candidate
	Statuses   map[string]Status
}

// Service runs lookups against a fixed list of sources.
type Service struct {
	sources []Source
	logger  *slog.Logger
}

// NewService returns a Service that queries sources in the order given. Candidates
// are returned in the same order.
func NewService(logger *slog.Logger, sources ...Source) *Service {
	return &Service{sources: sources, logger: logger}
}

type outcome struct {
	candidates []catalog.Candidate
	err        error
}

// Lookup queries all sources concurrently and waits for every one of them.
func (s *Service) Lookup(ctx context.Context, q catalog.Query) Result {
	outcomes := make([]outcome, len(s.sources))
	var wg sync.WaitGroup
	for i, source := range s.sources {
		wg.Add(1)
		go func() {
			defer wg.Done()
			candidates, err := source.Searcher.Search(ctx, q)
			outcomes[i] = outcome{candidates: candidates, err: err}
		}()
	}
	wg.Wait()

	result := Result{Query: q, Statuses: make(map[string]Status, len(s.sources))}
	for i, source := range s.sources {
		if err := outcomes[i].err; err != nil {
			result.Statuses[source.Name] = Status{Message: s.message(source.Name, err)}
			continue
		}
		candidates := outcomes[i].candidates
		result.Candidates = append(result.Candidates, candidates...)
		result.Statuses[source.Name] = Status{OK: true, Count: len(candidates)}
	}
	return result
}

// message returns text that is safe to show to users. Known unavailability is
// described; anything else is logged and reported generically.
func (s *Service) message(source string, err error) string {
	var unavailable *catalog.UnavailableError
	if errors.As(err, &unavailable) {
		return unavailable.Error()
	}
	s.logger.Error("lookup source failed", "source", source, "error", err)
	return "lookup failed"
}

package lookup

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"testing"

	"github.com/angelospillos/haiku-pwa/internal/catalog"
)

type fakeSearcher struct {
	candidates []catalog.Candidate
	err        error
}

func (f fakeSearcher) Search(context.Context, catalog.Query) ([]catalog.Candidate, error) {
	return f.candidates, f.err
}

func quietLogger() *slog.Logger {
	return slog.New(slog.NewTextHandler(io.Discard, nil))
}

func TestLookupMergesSourcesInOrder(t *testing.T) {
	comics := catalog.Candidate{Source: catalog.SourceComicsOrg, SourceID: "10"}
	inducks := catalog.Candidate{Source: catalog.SourceInducks, SourceID: "it/TL 3401"}
	service := NewService(quietLogger(),
		Source{Name: catalog.SourceComicsOrg, Searcher: fakeSearcher{candidates: []catalog.Candidate{comics}}},
		Source{Name: catalog.SourceInducks, Searcher: fakeSearcher{candidates: []catalog.Candidate{inducks}}},
	)

	result := service.Lookup(context.Background(), catalog.Query{Series: "Topolino", Number: "3401"})
	if len(result.Candidates) != 2 || result.Candidates[0] != comics || result.Candidates[1] != inducks {
		t.Errorf("Candidates = %+v, want comics.org then inducks", result.Candidates)
	}
	if s := result.Statuses[catalog.SourceComicsOrg]; !s.OK || s.Count != 1 {
		t.Errorf("comics.org status = %+v", s)
	}
}

func TestLookupKeepsWorkingSourcesWhenOneFails(t *testing.T) {
	inducks := catalog.Candidate{Source: catalog.SourceInducks, SourceID: "it/TL 3401"}
	failing := &catalog.UnavailableError{Source: catalog.SourceComicsOrg, Reason: "responded with HTTP 500"}
	service := NewService(quietLogger(),
		Source{Name: catalog.SourceComicsOrg, Searcher: fakeSearcher{err: failing}},
		Source{Name: catalog.SourceInducks, Searcher: fakeSearcher{candidates: []catalog.Candidate{inducks}}},
	)

	result := service.Lookup(context.Background(), catalog.Query{Series: "Topolino", Number: "3401"})
	if len(result.Candidates) != 1 || result.Candidates[0] != inducks {
		t.Errorf("Candidates = %+v, want only the inducks match", result.Candidates)
	}
	status := result.Statuses[catalog.SourceComicsOrg]
	if status.OK || status.Message != "comics.org responded with HTTP 500" {
		t.Errorf("comics.org status = %+v", status)
	}
}

func TestLookupHidesUnexpectedErrorDetails(t *testing.T) {
	service := NewService(quietLogger(),
		Source{Name: "broken", Searcher: fakeSearcher{err: errors.New("disk on fire at /secret/path")}},
	)

	result := service.Lookup(context.Background(), catalog.Query{Series: "X", Number: "1"})
	status := result.Statuses["broken"]
	if status.OK || status.Message != "lookup failed" {
		t.Errorf("status = %+v, want generic message", status)
	}
}

func TestLookupReportsEmptySourcesAsOK(t *testing.T) {
	service := NewService(quietLogger(),
		Source{Name: catalog.SourceInducks, Searcher: fakeSearcher{}},
	)
	result := service.Lookup(context.Background(), catalog.Query{Series: "X", Number: "1"})
	if s := result.Statuses[catalog.SourceInducks]; !s.OK || s.Count != 0 {
		t.Errorf("status = %+v, want ok with zero matches", s)
	}
}

// Package api serves the JSON API and the built web client.
package api

import (
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"path/filepath"
	"strconv"

	"github.com/angelospillos/haiku-pwa/internal/catalog"
	"github.com/angelospillos/haiku-pwa/internal/collection"
	"github.com/angelospillos/haiku-pwa/internal/lookup"
	"github.com/angelospillos/haiku-pwa/internal/photo"
)

const maxBodyBytes = 15 << 20

// Deps are the collaborators the handler needs.
type Deps struct {
	Logger           *slog.Logger
	Collection       *collection.Store
	Lookup           *lookup.Service
	InducksAvailable bool
	WebDir           string
}

type handlers struct {
	deps Deps
}

// NewHandler returns the complete HTTP handler: API routes, the web client and
// the middleware that wraps them.
func NewHandler(deps Deps) http.Handler {
	h := &handlers{deps: deps}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/health", h.health)
	mux.HandleFunc("GET /api/collection", h.listCollection)
	mux.HandleFunc("GET /api/collection/check", h.checkCollection)
	mux.HandleFunc("POST /api/collection", h.addComic)
	mux.HandleFunc("GET /api/comics/{id}/photo", h.comicPhoto)
	mux.HandleFunc("DELETE /api/comics/{id}", h.removeComic)
	mux.HandleFunc("GET /api/lookup", h.lookupIssue)
	mux.HandleFunc("/api/", notFound)
	mux.Handle("/", newWebHandler(deps.WebDir))

	return withMiddleware(deps.Logger, mux)
}

type healthResponse struct {
	OK      bool `json:"ok"`
	Inducks bool `json:"inducks"`
}

type comicDTO struct {
	ID              int64  `json:"id"`
	Series          string `json:"series"`
	Number          string `json:"number"`
	Source          string `json:"source"`
	SourceURL       string `json:"sourceUrl"`
	SeriesTitle     string `json:"seriesTitle"`
	Title           string `json:"title"`
	PublicationDate string `json:"publicationDate"`
	CoverURL        string `json:"coverUrl"`
	PhotoURL        string `json:"photoUrl"`
	CreatedAt       string `json:"createdAt"`
}

func toComicDTO(c collection.Comic) comicDTO {
	return comicDTO{
		ID:              c.ID,
		Series:          c.Series,
		Number:          c.Number,
		Source:          c.Source,
		SourceURL:       c.SourceURL,
		SeriesTitle:     c.SeriesTitle,
		Title:           c.Title,
		PublicationDate: c.PublicationDate,
		CoverURL:        c.CoverURL,
		PhotoURL:        "/api/comics/" + strconv.FormatInt(c.ID, 10) + "/photo",
		CreatedAt:       c.CreatedAt.Format("2006-01-02T15:04:05.999999999Z07:00"),
	}
}

type collectionResponse struct {
	Items  []comicDTO `json:"items"`
	Series []string   `json:"series"`
}

type checkResponse struct {
	Owned bool      `json:"owned"`
	Item  *comicDTO `json:"item"`
}

type addRequest struct {
	Series string        `json:"series"`
	Number string        `json:"number"`
	Photo  string        `json:"photo"`
	Match  *matchRequest `json:"match"`
}

type matchRequest struct {
	Source          string `json:"source"`
	SourceID        string `json:"sourceId"`
	SourceURL       string `json:"sourceUrl"`
	SeriesTitle     string `json:"seriesTitle"`
	Title           string `json:"title"`
	PublicationDate string `json:"publicationDate"`
	CoverURL        string `json:"coverUrl"`
}

type addResponse struct {
	Item comicDTO `json:"item"`
}

type conflictResponse struct {
	Error string    `json:"error"`
	Item  comicDTO  `json:"item"`
}

type lookupResponse struct {
	Series     string                  `json:"series"`
	Number     string                  `json:"number"`
	Year       string                  `json:"year"`
	Candidates []catalog.Candidate     `json:"candidates"`
	Sources    map[string]sourceStatus `json:"sources"`
}

type sourceStatus struct {
	OK      bool   `json:"ok"`
	Count   int    `json:"count"`
	Message string `json:"message,omitempty"`
}

func (h *handlers) health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, healthResponse{OK: true, Inducks: h.deps.InducksAvailable})
}

func (h *handlers) listCollection(w http.ResponseWriter, r *http.Request) {
	comics, err := h.deps.Collection.List(r.Context())
	if err != nil {
		h.internalError(w, r, err)
		return
	}
	names, err := h.deps.Collection.SeriesNames(r.Context())
	if err != nil {
		h.internalError(w, r, err)
		return
	}

	items := make([]comicDTO, 0, len(comics))
	for _, c := range comics {
		items = append(items, toComicDTO(c))
	}
	if names == nil {
		names = []string{}
	}
	writeJSON(w, http.StatusOK, collectionResponse{Items: items, Series: names})
}

func (h *handlers) checkCollection(w http.ResponseWriter, r *http.Request) {
	query, problem := parseIssueQuery(r.URL.Query(), false)
	if problem != "" {
		writeError(w, http.StatusBadRequest, problem)
		return
	}

	comic, err := h.deps.Collection.Find(r.Context(), query.Series, query.Number)
	switch {
	case errors.Is(err, collection.ErrNotFound):
		writeJSON(w, http.StatusOK, checkResponse{Owned: false})
	case err != nil:
		h.internalError(w, r, err)
	default:
		dto := toComicDTO(comic)
		writeJSON(w, http.StatusOK, checkResponse{Owned: true, Item: &dto})
	}
}

func (h *handlers) addComic(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)
	var req addRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			writeError(w, http.StatusRequestEntityTooLarge, photoTooLargeMessage)
			return
		}
		writeError(w, http.StatusBadRequest, "Invalid JSON")
		return
	}

	series, seriesOK := bounded(req.Series, maxSeriesRunes)
	number, numberOK := bounded(req.Number, maxNumberRunes)
	switch {
	case series == "":
		writeError(w, http.StatusBadRequest, "Series is required")
		return
	case number == "":
		writeError(w, http.StatusBadRequest, "Issue number is required")
		return
	case !seriesOK || !numberOK:
		writeError(w, http.StatusBadRequest, "Series and issue number must be shorter")
		return
	}

	image, err := photo.ParseDataURL(req.Photo)
	switch {
	case errors.Is(err, photo.ErrTooLarge):
		writeError(w, http.StatusRequestEntityTooLarge, photoTooLargeMessage)
		return
	case err != nil:
		writeError(w, http.StatusBadRequest, photoRequiredMessage)
		return
	}

	comic, err := h.deps.Collection.Add(r.Context(), collection.NewComic{
		Series:    series,
		Number:    number,
		PhotoData: image.Data,
		PhotoExt:  image.Extension,
		Match:     sanitizeMatch(req.Match),
	})
	var duplicate *collection.DuplicateError
	switch {
	case errors.As(err, &duplicate):
		writeJSON(w, http.StatusConflict, conflictResponse{
			Error: "This issue is already in the collection",
			Item:  toComicDTO(duplicate.Existing),
		})
	case err != nil:
		h.internalError(w, r, err)
	default:
		writeJSON(w, http.StatusCreated, addResponse{Item: toComicDTO(comic)})
	}
}

func (h *handlers) removeComic(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(r)
	if !ok {
		writeError(w, http.StatusBadRequest, "Invalid id")
		return
	}
	err := h.deps.Collection.Remove(r.Context(), id)
	switch {
	case errors.Is(err, collection.ErrNotFound):
		writeError(w, http.StatusNotFound, "Not found")
	case err != nil:
		h.internalError(w, r, err)
	default:
		w.WriteHeader(http.StatusNoContent)
	}
}

var photoTypes = map[string]string{
	".jpg":  "image/jpeg",
	".png":  "image/png",
	".webp": "image/webp",
}

func (h *handlers) comicPhoto(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(r)
	if !ok {
		writeError(w, http.StatusNotFound, "Not found")
		return
	}
	file, err := h.deps.Collection.PhotoPath(r.Context(), id)
	if errors.Is(err, collection.ErrNotFound) {
		writeError(w, http.StatusNotFound, "Not found")
		return
	}
	if err != nil {
		h.internalError(w, r, err)
		return
	}
	if _, err := os.Stat(file); errors.Is(err, os.ErrNotExist) {
		writeError(w, http.StatusNotFound, "Not found")
		return
	} else if err != nil {
		h.internalError(w, r, err)
		return
	}

	if contentType, ok := photoTypes[filepath.Ext(file)]; ok {
		w.Header().Set("Content-Type", contentType)
	}
	w.Header().Set("Cache-Control", "private, max-age=86400")
	http.ServeFile(w, r, file)
}

func (h *handlers) lookupIssue(w http.ResponseWriter, r *http.Request) {
	query, problem := parseIssueQuery(r.URL.Query(), true)
	if problem != "" {
		writeError(w, http.StatusBadRequest, problem)
		return
	}

	result := h.deps.Lookup.Lookup(r.Context(), query)
	candidates := result.Candidates
	if candidates == nil {
		candidates = []catalog.Candidate{}
	}
	sources := make(map[string]sourceStatus, len(result.Statuses))
	for name, status := range result.Statuses {
		sources[name] = sourceStatus{OK: status.OK, Count: status.Count, Message: status.Message}
	}
	writeJSON(w, http.StatusOK, lookupResponse{
		Series:     query.Series,
		Number:     query.Number,
		Year:       query.Year,
		Candidates: candidates,
		Sources:    sources,
	})
}

func (h *handlers) internalError(w http.ResponseWriter, r *http.Request, err error) {
	h.deps.Logger.ErrorContext(r.Context(), "request failed",
		"method", r.Method, "path", r.URL.Path, "error", err)
	writeError(w, http.StatusInternalServerError, "Something went wrong on the server")
}

func pathID(r *http.Request) (int64, bool) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	return id, err == nil && id > 0
}

func notFound(w http.ResponseWriter, _ *http.Request) {
	writeError(w, http.StatusNotFound, "Not found")
}

package api

import (
	"net/url"
	"regexp"
	"strings"
	"unicode/utf8"

	"github.com/angelospillos/haiku-pwa/internal/catalog"
)

const (
	maxSeriesRunes = 100
	maxNumberRunes = 20
	maxYearRunes   = 10

	photoRequiredMessage = "A photo of the comic is required (JPEG, PNG or WebP, up to 10 MB)"
	photoTooLargeMessage = "Photo is too large (10 MB limit)"
)

var yearPattern = regexp.MustCompile(`^\d{4}$`)

// bounded collapses whitespace in value and reports whether the result fits in
// max characters. Over-long input is rejected rather than silently truncated.
func bounded(value string, max int) (string, bool) {
	cleaned := strings.Join(strings.Fields(value), " ")
	return cleaned, utf8.RuneCountInString(cleaned) <= max
}

// parseIssueQuery validates the series, number and optional year from a query
// string. It returns a user-facing problem description when the input is not
// acceptable.
func parseIssueQuery(values url.Values, allowYear bool) (catalog.Query, string) {
	series, seriesOK := bounded(values.Get("series"), maxSeriesRunes)
	number, numberOK := bounded(values.Get("number"), maxNumberRunes)
	var year string
	if allowYear {
		var yearOK bool
		year, yearOK = bounded(values.Get("year"), maxYearRunes)
		if !yearOK || (year != "" && !yearPattern.MatchString(year)) {
			return catalog.Query{}, "Year must have four digits"
		}
	}

	switch {
	case series == "":
		return catalog.Query{}, "Series is required"
	case number == "":
		return catalog.Query{}, "Issue number is required"
	case !seriesOK || !numberOK:
		return catalog.Query{}, "Series and issue number must be shorter"
	}
	return catalog.Query{Series: series, Number: number, Year: year}, ""
}

// sanitizeMatch keeps only the catalogue details the server can vouch for: a
// known source, and URLs that are plain http or https links. Anything else is
// dropped, so a crafted request cannot store a javascript: link.
func sanitizeMatch(in *matchRequest) *catalog.Candidate {
	if in == nil || (in.Source != catalog.SourceComicsOrg && in.Source != catalog.SourceInducks) {
		return nil
	}
	sourceID, _ := bounded(in.SourceID, 80)
	seriesTitle, _ := bounded(in.SeriesTitle, 200)
	title, _ := bounded(in.Title, 200)
	publicationDate, _ := bounded(in.PublicationDate, 40)
	return &catalog.Candidate{
		Source:          in.Source,
		SourceID:        sourceID,
		SourceURL:       httpURL(in.SourceURL, 300),
		SeriesTitle:     seriesTitle,
		Title:           title,
		PublicationDate: publicationDate,
		CoverURL:        httpURL(in.CoverURL, 500),
	}
}

func httpURL(value string, max int) string {
	text, ok := bounded(value, max)
	if !ok {
		return ""
	}
	u, err := url.Parse(text)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
		return ""
	}
	return text
}

package api

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"log/slog"
	"net/http"
	"runtime/debug"
	"time"
)

const contentSecurityPolicy = "default-src 'self'; " +
	"img-src 'self' data: blob: https: http:; " +
	"style-src 'self'; script-src 'self'; connect-src 'self'; " +
	"manifest-src 'self'; worker-src 'self'; " +
	"base-uri 'self'; form-action 'self'; frame-ancestors 'none'"

type requestIDKey struct{}

// withMiddleware wraps next with request IDs, structured access logging, panic
// recovery and security headers.
func withMiddleware(logger *slog.Logger, next http.Handler) http.Handler {
	return withRequestLog(logger, withSecurityHeaders(next))
}

func withSecurityHeaders(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		headers := w.Header()
		headers.Set("Content-Security-Policy", contentSecurityPolicy)
		headers.Set("X-Content-Type-Options", "nosniff")
		headers.Set("X-Frame-Options", "DENY")
		headers.Set("Referrer-Policy", "strict-origin-when-cross-origin")
		headers.Set("Permissions-Policy", "geolocation=(), microphone=()")
		next.ServeHTTP(w, r)
	})
}

type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (s *statusRecorder) WriteHeader(code int) {
	if s.status == 0 {
		s.status = code
	}
	s.ResponseWriter.WriteHeader(code)
}

func (s *statusRecorder) Write(data []byte) (int, error) {
	if s.status == 0 {
		s.status = http.StatusOK
	}
	return s.ResponseWriter.Write(data)
}

func withRequestLog(logger *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		id := newRequestID()
		recorder := &statusRecorder{ResponseWriter: w}
		recorder.Header().Set("X-Request-ID", id)
		r = r.WithContext(context.WithValue(r.Context(), requestIDKey{}, id))

		defer func() {
			if recovered := recover(); recovered != nil {
				logger.ErrorContext(r.Context(), "panic while serving request",
					"request_id", id, "panic", recovered, "stack", string(debug.Stack()))
				if recorder.status == 0 {
					writeError(recorder, http.StatusInternalServerError, "Something went wrong on the server")
				}
			}
			status := recorder.status
			if status == 0 {
				status = http.StatusOK
			}
			logger.InfoContext(r.Context(), "request",
				"request_id", id,
				"method", r.Method,
				"path", r.URL.Path,
				"status", status,
				"duration_ms", time.Since(start).Milliseconds(),
			)
		}()

		next.ServeHTTP(recorder, r)
	})
}

func newRequestID() string {
	buf := make([]byte, 8)
	if _, err := rand.Read(buf); err != nil {
		return "unknown"
	}
	return hex.EncodeToString(buf)
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

type errorResponse struct {
	Error string `json:"error"`
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, errorResponse{Error: message})
}

package api

import (
	"net/http"
	"os"
	"path"
	"path/filepath"
	"strings"
)

// newWebHandler serves the built web client from webDir. Real files are served
// as they are; any other GET request gets index.html so the single-page app can
// handle the route.
func newWebHandler(webDir string) http.Handler {
	files := http.FileServer(http.Dir(webDir))
	index := filepath.Join(webDir, "index.html")

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			w.Header().Set("Allow", "GET, HEAD")
			writeError(w, http.StatusMethodNotAllowed, "Method not allowed")
			return
		}

		name := strings.TrimPrefix(path.Clean("/"+r.URL.Path), "/")
		if name != "" {
			info, err := os.Stat(filepath.Join(webDir, filepath.FromSlash(name)))
			if err == nil && !info.IsDir() {
				files.ServeHTTP(w, r)
				return
			}
		}

		if _, err := os.Stat(index); err != nil {
			writeError(w, http.StatusServiceUnavailable, "The web client has not been built. Run make build or npm run build.")
			return
		}
		http.ServeFile(w, r, index)
	})
}

